    EZTR_Basic_ReplaceText(0x0200, 0x00, 0x10, 0xFE, 0x0201, 0xFFFF, 0xFFFF, false, "" "\x05" "\x17" "Hey! If I call you, press " "\xB6" " right" "\x11" "away!" "\x18" "\x11" "\x00" "\x13" "\x12" "\x05" "I can tell you're not very used to" "\x11" "your " "\x01" "Deku Scrub" "\x05" " body yet." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0201, 0x00, 0x00, 0xFE, 0x0202, 0xFFFF, 0xFFFF, false, "" "\x05" "All right, listen up! If you press" "\x11" "and hold " "\xB0" " as a Deku Scrub" "\x11" "while standing on a " "\x01" "Deku Flower" "\x05" "," "\x11" "you can " "\x01" "dive " "\x05" "into it." "\x10" "If you wait a bit before releasing" "\x11" "\xB0" ", you'll " "\x01" "launch " "\x05" "out of the" "\x11" "flower. Press " "\xB0" " while flying to" "\x11" "\x01" "descend" "\x05" "." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0202, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Did you get that?" "\x11" "\x02" " " "\x11" "\xC2" "No" "\x11" "Yes" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0203, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Are you sure?" "\x11" "\x00" "\x13" "\x13" "\x12" "\x05" "One more thing: Press " "\xB0" " when" "\x11" "you're on the ground to perform a" "\x11" "\x01" "spin attack" "\x05" "!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0204, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x17" "Ugh! That stench!" "\x18" "\x11" "\x1F" "\x00" "\x0A" "This place stinks just like that" "\x11" "\x01" "poison swamp" "\x05" "!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0205, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What do you think that is?" "\x11" "The " "\x01" "ashes " "\x05" "in the center of it still" "\x11" "look fresh..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0206, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "This looks pretty light." "\x11" "Well, don't just stand there--" "\x11" "Press " "\xB0" " to grab it and use " "\xBB" "\x11" "to move it!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0207, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "This torch is still warm..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0208, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Be careful..." "\x11" "I sense a lot of evil here." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0209, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Look!" "\x11" "From up here, we have a better" "\x11" "view of that shrine below. " "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x020A, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hey, I'm trying to tell you" "\x11" "something..." "\x11" "This torch is still warm, too." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x020B, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x020C, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What? It's an " "\x01" "icicle" "\x05" "!" "\x11" "It's just like the one we saw" "\x11" "outside!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x020D, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hmm...This is kind of big..." "\x11" "It's gonna take more than " "\x01" "average" "\x11" "strength " "\x05" "to move this thing!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x020E, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x020F, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What, you think you can push" "\x11" "down something this big just by" "\x11" "standing on top of it?" "\x11" "\x12" "You're going to have to find some" "\x11" "way to pound it down." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0210, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "W-What just happened?!" "\x11" "Everything has..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0211, 0x00, 0x11, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x1F" "\x00" "\x0A" "\x00" "\x1E" "\x29" "\x25" "\x05" "...started over..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0212, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Wha...What are you, anyway? " "\x11" "That song you played..." "\x11" "That instrument..." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0213, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "...That instrument!!!" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0214, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Wait! That's it!" "\x11" "Your instrument!!!" "\x11" "\x13" "\x12" "The " "\x01" "mask salesman" "\x05" " said that if" "\x11" "you got back the " "\x01" "precious thing" "\x11" "\x05" "that was stolen from you, he" "\x11" "could return you to normal!" "\x10" "Did you completely forget or" "\x11" "what?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0215, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "He gives me the creeps! That" "\x11" "mask salesman was the..." "\x11" "\x1F" "\x00" "\x14" "Sorry...just thinking aloud." "\x11" "\x12" "But " "\x01" "three days" "\x05" "? Even if we never" "\x11" "sleep, that still leaves us with a" "\x11" "measly " "\x01" "72 hours" "\x05" "!" "\x11" "Talk about demanding!" "\x10" "Well, don't just stand there!" "\x11" "We're going to see the" "\x11" "\x01" "Great Fairy" "\x05" "!" "\x11" "\x12" "Look, you wanna find the Skull" "\x11" "Kid, don't you?" "\x11" "\x13" "\x12" "The " "\x01" "Great Fairy" "\x05" " will know what" "\x11" "he's up to. She watches over" "\x11" "everything." "\x11" "\x12" "And just between you and me," "\x11" "the Skull Kid is no match for the" "\x11" "\x01" "Great Fairy" "\x05" "." "\x11" "\x12" "Go to the " "\x01" "shrine" "\x05" " near the" "\x11" "\x01" "North Gate" "\x05" ". You'll find the" "\x11" "\x01" "Great Fairy " "\x05" "in there!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0216, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That mask..." "\x11" "\x1F" "\x00" "\x28" "The Skull Kid uses the power of" "\x11" "that mask to do those terrible" "\x11" "things." "\x10" "Well...whatever it takes, we've" "\x11" "gotta do something about it." "\x11" "\x13" "\x12" "...The " "\x01" "swamp" "\x05" "," "\x01" " mountains" "\x05" ", " "\x01" "ocean " "\x05" "and" "\x11" "\x01" "canyon" "\x05" " that Tael was trying to" "\x11" "tell us about..." "\x11" "\x12" "I bet he was referring to the" "\x11" "\x01" "four areas" "\x05" " just outside town." "\x11" "There's one in each compass" "\x11" "direction." "\x10" "But what do you suppose he" "\x11" "meant by \"" "\x01" "the four who are" "\x11" "there" "\x05" "?\"" "\x11" "\x12" "I have no idea. He always" "\x11" "skips important stuff. I guess we" "\x11" "should just go and find out..." "\x11" "\x12" "If we go through that gate" "\x11" "straight ahead, we'll be heading in" "\x11" "the direction of the " "\x01" "swamp" "\x05" "." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0217, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Oh! I remember this!" "\x11" "\x13" "\x13" "\x12" "\x01" "Tael" "\x05" " and I drew this with the" "\x11" "Skull Kid when we first met him..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0218, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "He told us that he had been" "\x11" "fighting with his friends and that" "\x11" "they had left him all alone..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0219, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "I'm sure it was because he was" "\x11" "always playing tricks, so nobody" "\x11" "wanted to play with him." "\x11" "\x12" "But to do what he did just" "\x11" "because of that..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x021A, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "And once he got his " "\x01" "power" "\x05" "..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x021B, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x29" "\x25" "\x05" "Oh no! The Great Fairy!" "\x1C" "\x00" "\x14" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x021D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hey, aren't you going to the" "\x11" "\x01" "Great Fairy's shrine" "\x05" " near the" "\x11" "\x01" "North Gate" "\x05" "?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x021E, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That Skull Kid has gone too far!" "\x11" "We can't just let this happen!" "\x11" "\x13" "\x12" "Quick! We have to find the" "\x11" "\x01" "Stray Fairy" "\x05" " in town and return" "\x11" "the Great Fairy to normal!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x021F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What are you doing?" "\x11" "Aren't you gonna take this " "\x01" "fairy" "\x11" "\x05" "to the " "\x01" "shrine " "\x05" "near the " "\x01" "North" "\x11" "Gate" "\x05" "?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0220, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "The Great Fairy said the" "\x11" "\x01" "astronomer" "\x05" " knows the " "\x01" "Skull Kid" "\x05" "..." "\x11" "\x13" "\x12" "Hurry! We need to find a way to" "\x11" "get out of town and to the" "\x11" "\x01" "observatory" "\x05" "!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0221, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "He said the " "\x01" "secret route " "\x05" "is in" "\x11" "\x01" "East Clock Town" "\x05" "..." "\x11" "So why aren't you going there?" "\x11" "\x12" "Don't tell me you forgot" "\x11" "the " "\x01" "code" "\x05" "!!!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0222, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "I wonder how the " "\x01" "astronomer" "\x11" "\x05" "knows the " "\x01" "Skull Kid" "\x05" "?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0223, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What's the " "\x01" "Skull Kid " "\x05" "doing all the" "\x11" "way up there?!" "\x11" "\x13" "\x12" "Well, whatever..." "\x11" "But aren't you at least interested" "\x11" "in that thing that fell from the" "\x11" "moon?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0224, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "The door to the clock tower opens" "\x11" "only once a year--at " "\x01" "midnight" "\x05" " on" "\x11" "the eve of the " "\x01" "carnival" "\x05" "." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0225, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Did you hear those fireworks?" "\x11" "I think the clock tower door has" "\x11" "just " "\x01" "opened" "\x05" "!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0226, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hey, you! C'mon! Press " "\xB5" " and" "\x11" "talk to me!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0227, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x17" "There you go! See? You can do it" "\x11" "if you try!" "\x18" "\x11" "\x13" "\x12" "When I fly over to people or" "\x11" "objects, use " "\xB5" " to look at them" "\x11" "so you can talk to them." "\x11" "\x12" "Use " "\x01" "Z Targeting" "\x05" " to talk to people" "\x11" "even if they're far away." "\x11" " " "\x11" "\x12" "Or, if there's no one to target," "\x11" "you can use " "\xB5" " to look " "\x01" "straight" "\x11" "ahead" "\x05" ". " "\x11" "\x12" "But enough about that for now..." "\x11" "Come over to this " "\x01" "tree " "\x05" "and " "\x01" "check" "\x11" "\x05" "it out!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0228, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's strange, but the way you look" "\x11" "right now sort of looks like this" "\x11" "tree..." "\x11" "\x12" "It looks all dark and gloomy..." "\x11" "almost like it could start crying" "\x11" "any second now..." "\x11" "\x1F" "\x00" "\x0A" "How sad... " "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0229, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "The " "\x01" "four people" "\x05" " Tael talked" "\x11" "about..." "\x11" "\x13" "\x12" "Do you think he was talking about" "\x11" "the spirit that was " "\x01" "sealed inside" "\x11" "\x05" "that mask?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x022A, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x17" "...Oh! Hey, you were pretty good" "\x11" "out there!" "\x18" "\x11" "Have you done this before or" "\x11" "what?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x022B, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Now, just keep up that pace and" "\x11" "save the other " "\x01" "three" "\x05" "!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x022C, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hey!" "\x11" "\x13" "\x13" "\x12" "Um..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x022D, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "All that stuff I did to you..." "\x11" "...your horse..." "\x11" "I...I apologize." "\xBF" "", NULL);
