    EZTR_Basic_ReplaceText(0x022F, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "There! I apologized!" "\x11" "So don't hold it against me," "\x11" "got it?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0230, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Now then, we've helped the" "\x11" "princess just like the monkey" "\x11" "asked..." "\x11" "\x12" "So now our next stop is in the" "\x11" "\x01" "mountains" "\x05" "! Let's hurry and do" "\x11" "something about that Skull Kid!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0231, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "The quickest way to the " "\x01" "mountains" "\x11" "\x05" "is through the " "\x01" "North Gate" "\x05" "!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0232, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "The quickest way to the " "\x01" "ocean" "\x05" " is" "\x11" "through the " "\x01" "West Gate" "\x05" "!" "\xBF" "", NULL);
