    EZTR_Basic_ReplaceText(0x0234, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What's with that Deku Scrub?" "\x11" "It's just " "\x01" "sleeping " "\x05" "here like a lazy" "\x11" "fool! What a pain!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0235, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Isn't this the " "\x01" "Deku Scrub mark" "\x05" "?" "\x11" "I wonder if they worshiped here..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0236, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Whoa! He's frozen solid!" "\x11" "\x1F" "\x00" "\x0A" "Wow! He's one ancient Goron," "\x11" "isn't he?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0237, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What's that?" "\x11" "There's something in the middle of" "\x11" "that blizzard... " "\x11" "Can't you see it?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0238, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hey! Isn't this snowball bigger" "\x11" "than the others?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0239, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Up here! Take a look at this!" "\x11" "I bet if you had a weapon that" "\x11" "was strong enough, one shot from" "\x11" "it could " "\x01" "pierce " "\x05" "right through this!" "\x10" "Well, it might take two shots..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x023A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Aha! So the Gorons fall asleep if" "\x11" "they hear the " "\x01" "Goron's Lullaby" "\x05" "!" "\x11" "\x1F" "\x00" "\x0A" "That's convenient..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x023B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hey, how do you get up there?" "\x11" "I don't see anything to climb on!" "\x11" "\x13" "\x12" "What can we use?  There's really" "\x11" "nothing here besides that jiggly" "\x11" "blob." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x023C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Are these all piled on top of" "\x11" "one another?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x023D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "We've gathered them all together," "\x11" "so we just have to go to the" "\x11" "Clock Tower and call them!" "\x11" "\x12" "C'mon. Let's go before it's too" "\x11" "late! I've had enough of all this!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x023E, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x023F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "C'mon! What are you doing? You" "\x11" "can ask " "\x01" "Jim " "\x05" "about the " "\x01" "secret" "\x11" "route " "\x05" "to the " "\x01" "observatory" "\x05" "!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0240, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Oh, why do we have to play these" "\x11" "stupid brats' little games?" "\x11" "C'mon! Hurry up and find them" "\x11" "already!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0241, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "I can't believe you let those brats" "\x11" "beat you!" "\x11" "What are you waiting for?" "\x11" "Let's show 'em how it's done!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0242, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Don't you remember that" "\x11" "\x01" "Deku Scrub" "\x05" " who wanted the" "\x11" "\x01" "Moon's Tear" "\x05" "?" "\x11" "Don't tell me you forgot..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0243, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "All right, so we know where the" "\x11" "Skull Kid is. Let's go ask around" "\x11" "the Clock Tower. Maybe we'll learn" "\x11" "something!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0244, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Remember? You're a Deku, so why" "\x11" "don't you try using this " "\x01" "Deku" "\x11" "Flower" "\x05" "?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0245, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Only " "\x01" "\xE8" "\x05" " left until morning!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0246, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Whoa!!! Look at the time!" "\x11" "You don't even have " "\x01" "three days" "\x11" "\x05" "left!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0247, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Whoa!!! Look at the time! You" "\x11" "don't even have " "\x01" "two days " "\x05" "left!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0248, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Whoa!!! Look at the time! You" "\x11" "don't even have a " "\x01" "single day " "\x05" "left!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0249, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Whoa!!! Look at the time! You" "\x11" "don't even have " "\x01" "half a day" "\x05" " left!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x024A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hey...hang on! " "\x11" "Doesn't this look a little strange?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x024B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Isn't this..." "\x11" "a " "\x01" "Zora egg" "\x05" "?" "\x11" "I wonder how we can carry it?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x024C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That's a huge fish!" "\x11" "I bet that thing could eat a small" "\x11" "fish in a single bite..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x024D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hey, what do you think that is?" "\x11" "Out there in the bay, beneath" "\x11" "where the " "\x01" "gulls" "\x05" " are flying..." "\x11" "Can't you see it?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x024E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "I can't see it, but I sense there's" "\x11" "a thirst for blood looming all" "\x11" "around us..." "\x11" "\x12" "Don't you have a " "\x01" "mask" "\x05" " that can" "\x11" "summon the unseen?" "\xBF" "", NULL);
