    EZTR_Basic_ReplaceText(0x0254, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "...Is this a mirror?" "\x11" "This thing looks different from" "\x11" "your everyday mirror." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0255, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x1E" "\x29" "\x25" "That's no good!" "\x11" "\x01" "It's not stopping" "\x05" "!" "\x11" "It's hopeless!" "\x1C" "\x00" "\x28" "\xBF" "", NULL);
