    EZTR_Basic_ReplaceText(0x025D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Isn't that your " "\x01" "horse" "\x05" "?!?" "\x1C" "\x00" "\x28" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x025E, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "I smell salt in the air, so the" "\x11" "\x01" "ocean" "\x05" " must be near." "\x11" "But with this " "\x01" "tall fence " "\x05" "in the" "\x11" "way, we can't go any farther." "\x10" "If only you had a " "\x01" "horse " "\x05" "to ride," "\x11" "we could--" "\x1F" "\x00" "\x0A" "Oops!" "\x11" "\x13" "\x1F" "\x00" "\x0A" "Sorry." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x025F, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hmph! This fence is the worst!" "\x11" "If we want to get up there, we'll" "\x11" "have to jump this fence!" "\x11" "\x12" "But you can't do it like this." "\x11" "I guess we'll have to give up..." "\xBF" "", NULL);
