    EZTR_Basic_ReplaceText(0x0262, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "I thought this room was pretty" "\x11" "dark...but now I get it." "\x11" "\x13" "\x12" "!?!" "\x11" "Don't tell me you still haven't" "\x11" "figured it out?!?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0263, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Look!" "\x11" "Can't you use the " "\x01" "Hookshot" "\x05" " on" "\x11" "that chest?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0264, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "If you could somehow step on" "\x11" "top of that Octorok, I bet you'd" "\x11" "be able to climb onto that central" "\x11" "pillar." "\x10" "But the Octorok is so squishy and" "\x11" "it keeps squirming around..." "\x11" "There's gotta be something you" "\x11" "can do!" "\xBF" "", NULL);
