    EZTR_Basic_ReplaceText(0x0456, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Is that so?" "\x11" "Think about it, little guy!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0457, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x06" "Zero Rupees" "\x00" "?" "\x11" "Oh, that's a cruel joke!" "\xBF" "", NULL);
