    EZTR_Basic_ReplaceText(0x045E, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...Hang on there, little guy." "\x11" "I can't take any more deposits." "\x11" "Sorry..." "\xBF" "", NULL);
