    EZTR_Basic_ReplaceText(0x05E0, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "So, will you gaze into the" "\x11" "telescope?" "\x11" "\x02" "\xC2" "Yes" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05E1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...I see." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05E2, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Why did you stop? " "\x11" "Won't you look again?" "\x11" "\x02" "\xC2" "Yes" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05E3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That is one of the lunar rocks" "\x11" "that has been blazing from the" "\x11" "surface of the moon lately." "\x11" "\x12" "They fall from what looks to be" "\x11" "the moon's eye, so I call them" "\x11" "\x01" "Moon's Tears" "\x00" "." "\x11" "\x12" "They are rare stones, valued by" "\x11" "many in town." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05E4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x46" "Did you have another question" "\x11" "for me?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05E5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "To me, it seems as if the moon is" "\x11" "being pulled in by something and" "\x11" "is gradually drawing closer." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05E6, 0x0B, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xBB" ":Move " "\xB1" ":Quit " "\xB0" ":Zoom" "\x1A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05E7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Don't you sense the change in the" "\x11" "moon?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05E8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well...could you see it?" "\x11" "It already may be impossible to" "\x11" "stop its descent..." "\x11" "\x12" "All I can do is accept what the" "\x11" "cosmos has designed to be the" "\x11" "destiny for me and this planet." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05E9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "How was it?" "\x11" "It's looking worse, isn't it?" "\x11" "It would be nice if things just" "\x11" "stayed as they are now." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05EA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "How was it?" "\x11" "\x13" "\x13" "\x12" "My calculations suggest the moon" "\x11" "will fall in another " "\x01" "\xE7" "\x00" "." "\x11" "I'm just hoping I was thinking too" "\x11" "hard." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05EB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, could you see it?" "\x11" "This is no joke...the moon is" "\x11" "actually falling!" "\x11" "\x12" "At this pace, it should hit the" "\x11" "earth in just " "\x01" "\xE7" "\x00" "..." "\x11" "What can we possibly do?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05EC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x46" "Well, well...A strange-looking child" "\x11" "has joined me today..." "\x11" "\x13" "\x12" "Are you a new friend of the" "\x11" "Bombers gang?" "\x11" "\x13" "\x12" "...Hmmm." "\x11" "Your manners seem much better" "\x11" "than those of your mischievous" "\x11" "friend from the other day." "\x10" "\x1E" "\x69" "\x47" "Hrnf, hrnf, hrnf!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05ED, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That ill-mannered troublemaker" "\x11" "from the other day said he'd" "\x11" "break my instruments..." "\x11" "\x12" "He said he'd steal my " "\x01" "Moon's Tear" "\x00" "..." "\x11" "There was no stopping him." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05EE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Even now! Just watch him! He's" "\x11" "probably causing trouble around" "\x11" "the " "\x01" "clock tower" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05EF, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Will you gaze into the" "\x11" "telescope?" "\x11" "\x02" "\xC2" "Yes" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05F0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, why not? You must take an" "\x11" "interest in new things while you" "\x11" "are still young!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05F1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, did you find that" "\x11" "\x01" "troublemaker" "\x00" "?" "\x11" "\x13" "\x12" "You can zoom in with " "\xB0" "." "\x11" "Try looking near the " "\x01" "clock tower" "\x00" "." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05F2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, did you find that" "\x11" "\x01" "troublemaker" "\x00" "? And that loud" "\x11" "noise...What was that?" "\x11" "\x12" "Perhaps another " "\x01" "Moon's Tear" "\x00" " has" "\x11" "fallen nearby...Go through that" "\x11" "door and take a look outside." "\x19" "\xBF" "", NULL);
