    EZTR_Basic_ReplaceText(0x05F4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What could that " "\x01" "troublemaker" "\x00" " be" "\x11" "doing atop the " "\x01" "clock tower" "\x00" "?" "\x11" "\x13" "\x12" "I just hope he's not plotting" "\x11" "another one of his no-good" "\x11" "tricks..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05F5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, you're a child I've never seen" "\x11" "in town before. Are you a new" "\x11" "friend of the Bombers?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05F6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I always say that it is important" "\x11" "to develop your interests while" "\x11" "you are young!" "\x11" "\x12" "You can use this telescope to" "\x11" "look around town. If you're" "\x11" "interested, give it a try." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05F7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, how was it? Did you" "\x11" "discover anything interesting?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x05F8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, why not?" "\x11" "You should develop your interests" "\x11" "while you are still young!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x060E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x8B" "I've already sold out of my wares," "\x11" "and the carnival hasn't even" "\x11" "begun." "\x11" "\x12" "I'm thinking of closing up shop so" "\x11" "I can buy a gift for my wife and" "\x11" "return to her in my village!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x060F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x38" "\x81" "I've heard that a stone called the" "\x11" "\x01" "Moon's Tear " "\x00" "shines brighter than" "\x11" "any other in the land!" "\x11" "\x12" "If you've got one, I'd really like" "\x11" "to get it from you. My wife" "\x11" "would love it!" "\x11" "\x12" "If you give it to me, I'll give you" "\x11" "my spot here..." "\x11" "\x01" "Deku Flower" "\x00" " included!" "\x19" "\xBF" "", NULL);
