    EZTR_Basic_ReplaceText(0x061A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x69" "This poster's an eyesore! What a" "\x11" "sorry collection of cowards!!" "\x11" "Bluh-yek! Foo!" "\xE0" "\xBF" "", NULL);
