    EZTR_Basic_ReplaceText(0x0622, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6A" "Heigh-ho, heigh-ho!" "\x11" "I knew it..." "\x11" "It's startin' to feel like this job'll" "\x11" "be impossible." "\xE0" "\xBF" "", NULL);
