    EZTR_Basic_ReplaceText(0x0729, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What's the code?" "\x11" "\x01" "\xD1" "\x11" "\x00" "Pick numbers with " "\xBB" " and press" "\x11" "\xB0" " to decide." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x072A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x04" "Umm...That's right. If you know the" "\x11" "\x01" "code" "\x00" ", then you're a member, right?" "\x11" "OK, here you go!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x072B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Wrong!" "\x11" "\x13" "\x13" "\x12" "Jim said I can't let anyone who" "\x11" "doesn't know the " "\x01" "code " "\x00" "in. " "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x072C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x05" "Aw! No way! You finally got me!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x072D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, man! I didn't think you'd come" "\x11" "over here." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x072E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x02" "Huh?" "\x11" "We're playing a game right now!" "\x11" "Leave me alone!" "\xE0" "\xBF" "", NULL);
