    EZTR_Basic_ReplaceText(0x0730, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, guy!" "\x11" "How do you know our " "\x01" "secret" "\x11" "code" "\x00" "?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0731, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Nobody but Bombers know that" "\x11" "\x01" "code" "\x00" "! So why do you know it?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0732, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Listen, guy!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0733, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1F" "\x00" "\x0A" "\x1E" "\x69" "\x03" "You're pretty good!" "\x11" "\x13" "\x13" "\x12" "You managed to figure out a " "\x01" "code" "\x11" "\x00" "that only we know! Now that's" "\x11" "something! I like you!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0734, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What's your name, guy?" "\x11" "\x13" "\x13" "\x12" "\x1F" "\x00" "\x0A" "\x16" ", huh?" "\x11" "All right...That Skull Kid broke our" "\x11" "rules and is doing all kinds of" "\x11" "stuff..." "\x10" "I'm making " "\x01" "\x16" " " "\x00" "a new" "\x11" "member of the " "\x01" "Bombers" "\x00" " instead!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0735, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Tatl, you tell that Skull Kid he's" "\x11" "outta here! He's been actin' like" "\x11" "a real jerk lately!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0736, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x01" "Hey, " "\x01" "\x16" "\x00" "." "\x11" "Are you writing in your notebook?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0737, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "1. Find troubled people and add" "\x11" "    their names and pictures." "\x11" "    Only " "\x01" "20 people" "\x00" " will fit in" "\x11" "    your book." "\x10" "2. Promise to help them." "\x11" "    Mark promises with " "\x01" "Promise" "\x11" "    Stickers" "\x00" ". Don't be late" "\x11" "    fulfilling your promises!" "\x10" "3. Whenever you solve someone's" "\x11" "    problem, it makes you happy," "\x11" "    so a " "\x01" "Happy Sticker " "\x00" "will be" "\x11" "    added to your book." "\x10" "4. No removing stickers!" "\x11" "    Use Promise Stickers to keep" "\x11" "    track of people until everyone" "\x11" "    is happy." "\x10" "Don't forget the rules!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0738, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x01" "The Bombers Secret Society of" "\x11" "Justice forever!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x073A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You burst my balloon! " "\x11" "Don't be messin' with other" "\x11" "people's stuff! Ya won't be able" "\x11" "to handle the consequences, pal!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x073B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You burst my balloon! " "\x11" "Don't be messin' with other" "\x11" "people's stuff! Ya won't be able" "\x11" "to handle the consequences, pal!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x073C, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "There's a lot of " "\x01" "cool stuff" "\x00" " at that" "\x11" "telescope guy's place!" "\x11" "\x13" "\x12" "Oh, yeah...and, um..." "\x11" "\x1F" "\x00" "\x04" "\x17" "The Bombers Secret Society of" "\x11" "Justice forever!" "\x18" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x073D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "How old are you? You're not from" "\x11" "around here, are you? Why are" "\x11" "you dressed like that?" "\x11" "Why? Huh? Why?" "\x10" "Do you have any problems? Any?" "\x11" "If you do, tell it to us Bombers!" "\x11" "Tell us!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x073E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh! A Goron! Do you live in the" "\x11" "mountains? Why is Tatl with you?" "\x11" "Why? Huh? Why?" "\x11" "\x12" "Do you have any problems? Any?" "\x11" "If you do, you can tell us" "\x11" "Bombers! Tell us!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x073F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh! A Zora! Do you live in the" "\x11" "ocean? What's it like? Why is" "\x11" "Tatl with you? Why? Huh? Why?" "\x11" "\x12" "Do you have any problems? Any?" "\x11" "If you do, you can tell us" "\x11" "Bombers! Tell us!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0740, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Psst...Wanna know about the" "\x11" "Bombers?" "\x11" "\x02" "\xC2" "Yes" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0741, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Why don't you wanna know?" "\x11" "Why? Why?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0742, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x01" "Heh, heh! You can't tell anyone!" "\x11" "\x13" "\x13" "\x12" "Every Bomber has a " "\x01" "notebook" "\x00" "!" "\x11" "Here's how we use it:" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0743, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The Bombers gang is a Secret" "\x11" "Society of Justice. You can't tell" "\x11" "this to anybody..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0744, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x02" "What's with you? You're wearing a" "\x11" "weird hat for a Deku! Did you" "\x11" "come to town to play? I bet" "\x11" "nobody will play with you, right?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0745, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The adults are all busy getting" "\x11" "ready for the carnival!" "\x11" "\x13" "\x12" "The " "\x01" "old astronomer" "\x00" " at the" "\x11" "\x01" "observatory" "\x00" " outside town is the" "\x11" "only one who'll spend any time" "\x11" "playing with us kids." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0746, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The adults are busy trying to" "\x11" "decide whether or not to hold the" "\x11" "carnival!" "\x11" "\x12" "The " "\x01" "old astronomer" "\x00" " at the" "\x11" "\x01" "observatory" "\x00" " outside town is the" "\x11" "only one who'll spend any time" "\x11" "playing with us kids!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0747, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We " "\x01" "Bombers" "\x00" " have our " "\x01" "hideout" "\x00" " at" "\x11" "the " "\x01" "observatory" "\x00" "." "\x11" "\x13" "\x12" "You have to take a " "\x01" "secret route" "\x11" "\x00" "to get to it." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0748, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh! Don't be telling " "\x01" "Jim " "\x00" "in " "\x01" "North" "\x11" "Clock Town " "\x00" "that I told you that!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0749, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The " "\x01" "secret route" "\x00" " to the" "\x11" "\x01" "Observatory" "\x00" "? How do you know" "\x11" "about that?" "\x11" "\x12" "Only " "\x01" "Jim" "\x00" " and us are supposed to" "\x11" "know about that " "\x01" "secret route" "\x00" "..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x074A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Don't tell anyone that you heard" "\x11" "about the secret route from me," "\x11" "got it?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x074B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x01" "Hey, buddy! Have you found any" "\x11" "troubled people? If you do, add" "\x11" "'em to your " "\x01" "notebook" "\x00" "!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x074C, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Do you remember how to use your" "\x11" "\x01" "notebook" "\x00" "?" "\x11" "\x02" "\xC2" "Yes" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x074D, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "All right! The Bombers Secret" "\x11" "Society of Justice forever!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x074E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Did you memorize the " "\x01" "code" "\x00" "?" "\x11" "If only you were human...then I" "\x11" "could make you a " "\x01" "Bombers" "\x11" "\x00" "member...Too bad!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x074F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x03" "You're pretty good for" "\x11" "a Deku Scrub!" "\x11" "\x13" "\x12" "If only you were human..." "\x11" "\x13" "\x13" "\x12" "Then I could give you an original" "\x11" "\x01" "Bombers' Notebook" "\x00" " and make you a" "\x11" "member..." "\x11" "\x12" "What do you guys think?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0750, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "No way! No Scrubs!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0751, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I guess not...Once, we let some" "\x11" "kid who wasn't human join our" "\x11" "gang, and, boy, did we ever regret" "\x11" "it! Sorry!" "\x10" "But I'll teach you the " "\x01" "code" "\x00" ", just" "\x11" "like I promised. I can tell you only" "\x11" "\x01" "once" "\x00" ", though, so pay close" "\x11" "attention!" "\x10" "Are you ready?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0752, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The code is " "\x01" "\xDF" "\x00" "!" "\x11" "The entrance to our " "\x01" "hideout " "\x00" "is in" "\x11" "\x01" "East Clock Town" "\x00" "!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0753, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x03" "Are you the guy who just popped" "\x11" "that up there?" "\x11" "Whoa!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0754, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, just for you, guy, I can make" "\x11" "you a member of our gang, the" "\x11" "\x01" "Bombers" "\x00" "!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0755, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But there is a test for becoming" "\x11" "a " "\x01" "Bombers " "\x00" "member. C'mon!" "\x11" "Give it a try!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0756, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Are you ready?" "\x11" "\x02" " " "\x11" "\xC2" "Yes" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0757, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you can find all" "\x01" " five " "\x00" "of us by" "\x11" "\x01" "tomorrow morning" "\x00" ", I'll teach you" "\x11" "our secret code. Ready?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0758, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x00" "What's the deal, guy?" "\x11" "You dress like you think you're all" "\x11" "cool, but you're nothing special!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0759, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What? Whaddya mean?!" "\x11" "Don't you want to join the" "\x11" "\x01" "Bombers" "\x00" "?" "\x19" "\xBF" "", NULL);
