    EZTR_Basic_ReplaceText(0x0841, 0x06, 0x30, 0xFE, 0xFFFF, 0x0014, 0xFFFF, false, "" "\x01" "Green Potion: 10 Rupees" "\x11" "\x00" "This works very well when you're" "\x11" "low on magic power." "\x1A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0842, 0x06, 0x31, 0xFE, 0xFFFF, 0x000A, 0xFFFF, false, "" "Green Potion: 10 Rupees" "\x11" " " "\x11" "\x02" "\xC2" "I'll buy it" "\x11" "No thanks" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0843, 0x06, 0x30, 0xFE, 0xFFFF, 0x003C, 0xFFFF, false, "" "\x01" "Blue Potion: 60 Rupees" "\x11" "\x00" "I just brewed up this cure-all!" "\x11" "It goes down easy and gets right" "\x11" "to work." "\x1A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0844, 0x06, 0x31, 0xFE, 0xFFFF, 0x003C, 0xFFFF, false, "" "Blue Potion: 60 Rupees" "\x11" " " "\x11" "\x02" "\xC2" "I'll buy it" "\x11" "No thanks" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0845, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Mmm...If only I had some fragrant" "\x11" "mushrooms..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0846, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I can't sell it to you if you have" "\x11" "nothing to keep it in!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0847, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Are you trying to play a trick on" "\x11" "me?!? You don't have enough" "\x11" "\x06" "Rupees" "\x00" "!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0848, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Take care...Tee-hee-hee!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0849, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Have you seen an old hag named" "\x11" "Koume who looks just like me?" "\x11" "She hasn't come back from" "\x11" "Picking mushrooms..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x084A, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Gone out back to the woods on" "\x11" "a little errand." "\x11" "            -Kotake" "\x11" "            The Manager" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x084B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xCB" "Tee-hee-hee!" "\x11" "...Hmm...Did you need me for" "\x11" "something?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x084C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x01" "I'm heading back to the potion" "\x11" "shop for now, so I'm counting on" "\x11" "you." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x084D, 0x00, 0x00, 0xFE, 0x084E, 0xFFFF, 0xFFFF, false, "" "...Could you, by chance, be a boat" "\x11" "cruise passenger?" "\x11" "\x13" "\x12" "It's unfortunate, but Koume is" "\x11" "missing..." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x084E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Help me look for her..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x084F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x01" "Koume!" "\x11" "Where are you?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0850, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x00" "Ah...hmm...Now that's a problem..." "\x11" "See, we sell potions to humans" "\x11" "only." "\x11" "\x12" "I don't think they'll work on" "\x11" "anything but humans...Sorry, but" "\x11" "you'll have to leave." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0851, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0852, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x00" "Ohh! Owow-ow!" "\x11" "Help meeee!" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0853, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x00" "I was just busy minding my own" "\x11" "business, picking mushrooms," "\x11" "when..." "\x11" "BAM! I got hit from behind!" "\x10" "That pesky Skull Kid!" "\x11" "Did he think an old hag wouldn't" "\x11" "recognize him if he hid his face?" "\x11" "\x12" "\x1E" "\x39" "\x00" "Oh, ow! To think he's that" "\x11" "powerful...and now I can't even" "\x11" "move!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0854, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You! Don't you have anything that" "\x11" "gives you " "\x01" "energy" "\x00" "?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0855, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ah! What is this?!" "\x11" "You're no help..." "\x11" "\x13" "\x12" "I say, you're not at all what you" "\x11" "make yourself out to be!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0856, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x00" "Ow-ow-yeow!" "\x11" "Don't you feel obligated to help a" "\x11" "sorry old hag when you see one?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0857, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ooh!" "\x11" "Feel the energy flow!" "\x11" "\x13" "\x12" "Koume is revived!!!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0858, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You saved me!" "\x11" "\x13" "\x13" "\x12" "I'm the swamp tour guide. I run" "\x11" "the boat cruise, so come by if" "\x11" "you want a free ride." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0859, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x01" "Oh! Thanks for what you did back" "\x11" "there!" "\x11" "\x13" "\x12" "In a special deal just for you, I'll" "\x11" "let you take this cruise for free." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x085A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC7" "If you're going on the boat cruise," "\x11" "buy your ticket here." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x085B, 0x00, 0x00, 0xFE, 0xFFFF, 0x0032, 0x000A, false, "" "...Umm..." "\x11" "\x13" "\x13" "\x12" "Adults: " "\x06" "50 Rupees" "\x11" "\x00" "Children: " "\x06" "10 Rupees" "\x11" "\x00" "Group discounts for 15 or more..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x085C, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "So...going on the cruise?" "\x11" "\x02" " " "\x11" "\xC2" "Yes" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x085D, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x085E, 0x00, 0x00, 0xFE, 0xFFFF, 0x0032, 0xFFFF, false, "" "Great. Kids are " "\x06" "10 Rupees" "\x00" "!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x085F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC7" "Well, come see me if you change" "\x11" "your mind..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0860, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "All right. Well, take care..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0861, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC7" "Well, welcome back. If you're ever" "\x11" "in the mood, come again..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0862, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x01" "Old Koume's Boat Cruise" "\x11" "\x00" "Ticket office closed." "\x11" "\x13" "\x12" "Please inquire at the Magic Hags'" "\x11" "\x01" "Potion Shop " "\x00" "near the edge of the" "\x11" "swamp." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0863, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ah, yes, we've got a special going" "\x11" "on right now, so we're giving this" "\x11" "out for free!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0864, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\x00" "Ah! That color! That smell..." "\x11" "That's definitely Kotake's..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0865, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\x00" "Ack! Now I've done it! I've gone" "\x11" "and attracted some weirdo's" "\x11" "attention! Umm...I'll just play dead." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0866, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "........." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0867, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC7" "Well, this is where the boat" "\x11" "cruise leaves from, but" "\x11" "unfortunately it's for humans only." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0868, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC7" "Oh! Thanks for what you did back" "\x11" "there!" "\x11" "\x13" "\x12" "As a special just for you, I'll let" "\x11" "you take this cruise for free." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0869, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, but wait...Yes. Just as I" "\x11" "thought..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x086A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It seems the poison swamp has" "\x11" "been cleaned up, so why not try" "\x11" "something that's more interesting?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x086B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "How about a little game?" "\x11" "I'll fly around on my broom, and" "\x11" "you try to hit my target?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x086C, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Doesn't it sound fun?" "\x11" "Well, wanna try?" "\x11" "\x02" "\xC2" "Sure" "\x11" "No thanks" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x086D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\x00" "Why not?!? You don't like to play" "\x11" "with us old folk?" "\x11" "\x13" "\x12" "Oh, I see how it is! If that's the" "\x11" "case, then shoo! Shoo!" "\x11" "Off you go!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x086E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xCC" "Tee-hee-hee!" "\x11" "That's the way to go!" "\x11" "\x13" "\x12" "But let me explain!" "\x11" "You're not aiming for " "\x01" "me" "\x00" " with that" "\x11" "bow. You're aiming for the " "\x01" "target" "\x00" "!" "\x11" "\x12" "If you hit me, I'll never forgive" "\x11" "you." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x086F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x01" "Ready?" "\x11" "Here we go!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0870, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xCC" "Tee-hee-hee-hee!" "\x11" "So you do want to try?" "\x11" "The old hag sees all!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0871, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...Hmm...Let's see." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0872, 0x00, 0x00, 0xFE, 0xFFFF, 0x000A, 0xFFFF, false, "" "\x1E" "\x39" "\x01" "Ho! You again?" "\x11" "If you'd like to play that game," "\x11" "it's " "\x06" "10 Rupees" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0873, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What'll it be?" "\x11" " " "\x11" "\x02" "\xC2" "I'll play" "\x11" "No thanks" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0874, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, you do that then. You'll" "\x11" "never be an upstanding adult if" "\x11" "you don't challenge yourself." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0875, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Why, you don't have enough" "\x11" "Rupees! Don't you try to make" "\x11" "a fool out of me!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0876, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Your last record was" "\x11" "\x01" "\x0B" "\x00" " hits." "\x11" "\x1E" "\x39" "\x01" "If you get more than that, you'll" "\x11" "win a " "\x01" "prize" "\x00" ". " "\x10" "Now, then. Here we go!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0877, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x00" "To shoot a pathetic old hag" "\x11" "\x01" "10 times" "\x00" "! I'd like to see your" "\x11" "parents' faces when they hear" "\x11" "of it!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0878, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x01" "\xDB" " hits" "\x11" "Say...you're pretty good." "\x11" "\x13" "\x12" "Well, as I promised..." "\x11" "Here! Take this." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0879, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It may be impossible to break this" "\x11" "record." "\x11" "\x13" "\x12" "But if you want to try again, just" "\x11" "ask me!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x087A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC7" "Wow! That was sloppy!" "\x11" "\xDB" " hits, eh..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x087B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Why don't you come back after" "\x11" "you practice up a bit!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x087C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC7" "Wow. That was sloppy!" "\x11" "\x01" "\xDB" " hits," "\x00" " huh?" "\x11" "\x13" "\x12" "You have to get more than " "\x01" "\x0B" " hits" "\x00" "." "\x11" "Otherwise, no prize." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x087D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xDB" "!" "\x11" "Pretty good, considering..." "\x11" "\x13" "\x12" "\x1E" "\x39" "\x01" "Well, as I promised..." "\x11" "Here! Take this." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x087E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Now wasn't that fun? If you'd like" "\x11" "to play again, come back and see" "\x11" "me...Tee-hee!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x087F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x00" "Hey! Hey! Hey!" "\x11" "What are you aiming for, anyway?" "\x11" "That's it! We're done!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0880, 0x06, 0x30, 0xFE, 0xFFFF, 0x003C, 0xFFFF, false, "" "\x01" "Blue Potion: 60 Rupees" "\x11" "\x00" "Actually, I can't get the" "\x11" "ingredients for this, so I'm sold" "\x11" "out. Sorry." "\x1A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0881, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What's that? You want a " "\x03" "Blue" "\x11" "Potion," "\x00" " do you?" "\x11" "\x13" "\x12" "Well, you gave me a mushroom, so" "\x11" "I'll give you one for free." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0882, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Sniff, sniff...I think I'm smelling" "\x11" "the light fragrance of mushrooms... " "\x11" "Do you have any?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0883, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x01" "Mmmm...What a scent!" "\x11" "Oh, you did a great job finding" "\x11" "this one!" "\x11" "\x12" "I just haven't been able to get my" "\x11" "hands on any of them, and that" "\x11" "put me in a real pinch!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0884, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, I can use this to make" "\x11" "something, so come back later." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0885, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What I use this for is a trade" "\x11" "secret! Sorry, but you'll have to" "\x11" "come back later." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0886, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Long ago, this powerful nose of" "\x11" "mine could detect them wherever" "\x11" "they grew..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0887, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But lately my nose has lost its" "\x11" "touch..." "\x11" "\x13" "\x12" "\x1E" "\x39" "\x00" "It's tough getting old..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0888, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x01" "Mmm..." "\x11" "This mushroom smells nice, too." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0889, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'll pay a fortune for it." "\x11" "You must sell it to me!" "\x11" "Here!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x088A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Keep bringing 'em in!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x088B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you have a mushroom, I'll buy it." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x088C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But next time you'll have to pay" "\x11" "for it. Oh...and don't tell Koume!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x088D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you take a nice picture from" "\x11" "the boat, take it to that fella" "\x11" "over there." "\x11" "\x12" "All right...The boat's leaving!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x088E, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Why, your bottle's already full!" "\x18" "\x11" "\x13" "\x13" "\x12" "I can't sell you any " "\x01" "potions" "\x00" " unless" "\x11" "you have an " "\x01" "empty bottle" "\x00" "!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x088F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What are you hangin' around for?" "\x11" "I hate slackers!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0890, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh! Aren't you wearing a fine" "\x11" "mask!" "\x11" "\x13" "\x12" "With that mask, you can find the" "\x11" "\x01" "mushrooms" "\x00" " that grow in the" "\x11" "\x01" "woods" "\x00" "." "\x11" "\x12" "Find a bunch and bring 'em here!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0898, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\xA8" "Everyone!" "\x11" "Hurry up and get that cauldron" "\x11" "ready!!!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0899, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\xA8" "I haven't seen your face before." "\x11" "Are you visiting?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x089A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\xA8" "Usually, I don't allow the likes of" "\x11" "you in my Royal Chamber, but" "\x11" "today is different!" "\x11" "\x12" "We're about to punish the foolish" "\x11" "\x01" "monkey" "\x00" " who " "\x01" "kidnapped" "\x00" " the " "\x01" "Deku" "\x11" "princess" "\x00" "!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x089B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "He has insulted the Royal Family." "\x11" "I'll show him what happens when" "\x11" "you do that!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x089C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That " "\x01" "foolish monkey" "\x00" " is up in that" "\x11" "\x01" "cage" "\x00" ". Take a good look at his" "\x11" "face!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x089D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\xA8" "How about that?" "\x11" "...Hot, isn't it?" "\x11" "\x13" "\x12" "The monkey shall suffer and" "\x11" "suffer 'til he can suffer no more!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x089E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You shall know the wrath of a" "\x11" "king whose darling princess was" "\x11" "taken away from him!!!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x089F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\xA8" "Suffer!" "\x11" "I shall prolong his suffering!" "\x11" "Foolish" "\x01" " monkey" "\x00" "!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08A0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\xA8" "Oh, my princess! My darling" "\x11" "princess!!! You are all right?" "\x11" "I was so worried." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08A1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\xA8" "Hasty decision making is my" "\x11" "weakness...This time, more than" "\x11" "ever, it has become clear to me." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08A2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, strange traveler, there is" "\x11" "little I can do. Please rest a bit" "\x11" "before going." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08A3, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\xA8" "Everyone, did you hear that?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08A4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This melody, which only the Deku" "\x11" "Royal Family knows..." "\x11" "\x13" "\x12" "It proves the foolish monkey" "\x11" "deceived the princess so he could" "\x11" "enter the temple!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08A5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\xA8" "Everyone!" "\x11" "Let the monkey's punishment" "\x11" "commence!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08CA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "They keep saying that I kidnapped" "\x11" "her. No matter how many times" "\x11" "they say it, it's not going to bring" "\x11" "the" "\x01" " princess" "\x00" " back! " "\x10" "If they're not careful, the " "\x01" "princess" "\x11" "\x00" "will fall victim to a monster!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08CB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Please, believe my words..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08CC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x29" "\x01" "Oh! You...How did you get here?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08CD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Shhh!" "\x11" "If they see you, they'll capture" "\x11" "you!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08CE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What? My brothers asked for" "\x11" "your help? Ugh...I'm terribly" "\x11" "sorry..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08CF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Just try to cut my " "\x01" "rope" "\x00" ". We'll" "\x11" "talk after that!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08D0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What are you doing? Quick--cut" "\x11" "this " "\x01" "rope" "\x00" "!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08D1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Huh? That guy..." "\x11" "Where did he go???" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08D2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x29" "\x21" "Hmm...No good, after all!" "\x11" "\x13" "\x13" "\x12" "Wait...You don't happen to have" "\x11" "something that can make a lot of " "\x11" "noise...like a loud " "\x01" "instrument " "\x00" "with" "\x11" "sound that carries a long way?" "\x10" "If you have one, " "\x01" "show" "\x00" " it to me!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08D3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you have one, show me! We" "\x11" "have to use it..." "\x11" "\x01" "\x13" "\x12" "Please! An instrument that can " "\x11" "blare out a lot of sound that'll" "\x11" "carry a long way" "\x00" "!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08D4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That tiny thing will never do. Its" "\x11" "sound won't carry far enough..." "\x11" "\x13" "\x12" "Don't you have something else?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08D5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hmm...That definitely makes noise..." "\x11" "but that's not it!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08D6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That's not it." "\x11" "One with " "\x01" "blaring " "\x00" "sound that" "\x11" "carries even farther!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08D7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Huh? That guy..." "\x11" "Where did he go?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08D8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x29" "\x01" "Oh! You have them! You do!" "\x11" "Just like the princess..." "\x11" "\x01" "Deku Pipes" "\x00" "!" "\x11" "Those will work great!!!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08D9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "By the way..." "\x1F" "\x00" "\x14" "\x17" "\x01" "who" "\x00" " are you?" "\x18" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08DA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "By the way..." "\x1F" "\x00" "\x14" "\x17" "\x01" "who" "\x00" " are you?" "\x18" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08DB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "By the way..." "\x1F" "\x00" "\x14" "\x17" "\x01" "who" "\x00" " are you?" "\x18" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08DC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...Whoa!" "\x11" "That's not important now..." "\x11" "Just listen to me!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08DD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I was trying to find out about the" "\x11" "poison in the swamp, so I went to" "\x11" "\x01" "Woodfall Temple" "\x00" " above the" "\x11" "waterfall." "\x10" "But the temple had become a" "\x11" "\x01" "monster's lair" "\x00" ", and the princess" "\x11" "was captured by the monster..." "\x11" "\x12" "Since the Deku king thinks I" "\x11" "kidnapped the princess, he won't" "\x11" "listen to a word I say." "\x11" "\x12" "Now the princess is in trouble, so" "\x11" "I must somehow hurry to the" "\x11" "\x01" "temple" "\x00" " and save her!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08DE, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Do you understand my plight?" "\x11" " " "\x11" "\x02" "\xC2" "No" "\x11" "Yes" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08DF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Then I will tell you and tell you" "\x11" "until it is clear to you!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08E0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "So then, that means..." "\x11" "\x13" "\x13" "\x12" "You will go in my place and save" "\x11" "the princess!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08E1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "OK, now I'll teach you the " "\x01" "melody" "\x11" "\x00" "that opens the " "\x01" "temple" "\x00" "." "\x11" "\x13" "\x12" "The " "\x01" "princess" "\x00" " taught it to me!" "\x11" "We can't let them hear us, so I'll" "\x11" "sing it softly..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08E2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You'd better take the " "\x01" "shortcut" "\x00" " the" "\x11" "\x01" "Deku people" "\x00" " use to get to" "\x11" "\x01" "Woodfall Temple" "\x00" "." "\x11" "\x12" "But you must hurry! If you don't," "\x11" "I will be punished by the Deku" "\x11" "king!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08E3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I understand, Princess. Forget" "\x11" "about that. Has the temple been" "\x11" "returned to normal?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08E4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Really? So you're called" "\x11" "\x16" ", are you?" "\x11" "\x13" "\x12" "Thank you for keeping your" "\x11" "promise to me." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08E5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x16" ", I'm sorry for all that" "\x11" "trouble." "\x11" "\x13" "\x12" "Now it looks like we monkeys and" "\x11" "the Deku Scrubs can start getting" "\x11" "along again." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08E6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...You know, the swamp may be" "\x11" "back to normal, but something still" "\x11" "gives me a bad feeling..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08E7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I wonder what it could be?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08E8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x29" "\x63" "Ooh! Hot! Hot!" "\x11" "St-stop it! Please!!!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08E9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "They keep saying that I kidnapped" "\x11" "her. No matter how many times" "\x11" "they say it, it's not going to bring" "\x11" "the" "\x01" " princess" "\x00" " back!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08EA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "........." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08EB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Why won't they believe what I" "\x11" "say?" "\x11" "\x13" "\x12" "...Fine! I get it! Then I shall say" "\x11" "nothing more to you! Punish me or" "\x11" "do whatever else you might!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x08EC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I have nothing else to say to you" "\x11" "Deku Scrubs!" "\x11" "Do as you will!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0910, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ah! Help me!" "\x11" "I am not a monster!" "\x11" "\x13" "\x12" "The spider's curse..." "\x11" "It made me this way..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0911, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I beg of you..." "\x01" "In here" "\x00" "...Find them" "\x11" "\x01" "all" "\x00" "...The " "\x01" "gold" "\x00" " ones...The cursed" "\x11" "\x01" "spiders" "\x00" "...Defeat them...Quickly!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0912, 0x00, 0x00, 0x52, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "And when you defeat them..." "\x11" "don't forget...the " "\x01" "spider token" "\x00" "...it" "\x11" "contains the spider's spirit..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0913, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you lift the curse...I'll teach you" "\x11" "...something good...Hurry...Please" "\x11" "...This is awful..." "\xE0" "\xBF" "", NULL);
