    EZTR_Basic_ReplaceText(0x0915, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Make me...normal again...I'll teach" "\x11" "you something...something good..." "\x11" "Please...help me..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0916, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ohhh! I've been saved! I thought" "\x11" "that I was going to die..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0917, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You see, a while back, someone" "\x11" "told me I could become rich and" "\x11" "he gave me this " "\x01" "mask" "\x00" "." "\x11" "\x12" "He said the instructions were" "\x11" "inscribed somewhere in here, but" "\x11" "when I went to look, I was" "\x11" "cursed!" "\x10" "If I had known it would be such" "\x11" "an ordeal, I never would have" "\x11" "taken it. Here! Take it!" "\x11" "It's yours!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0918, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I've had enough of this..." "\x11" "\x13" "\x13" "\x12" "As soon as I get it together," "\x11" "I'm going home." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0919, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ohhh! I've been saved. I thought" "\x11" "that I was going to die..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x091A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You see, a while back, someone" "\x11" "told me that I could become rich" "\x11" "and he gave me this " "\x01" "mask" "\x00" "." "\x11" "\x12" "He said the instructions were" "\x11" "inscribed somewhere in here, but" "\x11" "when I went to look, I was" "\x11" "cursed!" "\x10" "If I had known it would be such" "\x11" "an ordeal, I never would have" "\x11" "taken it. I'm getting rid of it!" "\xE0" "\xBF" "", NULL);
