    EZTR_Basic_ReplaceText(0x091C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x29" "\x13" "Rrr-ruff!" "\x11" "Stupid master...His eyes are" "\x11" "always filled with greed and" "\x11" "desire..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x091E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x29" "\x0B" "Rrr-ruff!" "\x11" "I've had it with this foolish" "\x11" "master..." "\x11" "\x12" "What's a racing dog like me doing" "\x11" "in a place like this?" "\x11" "\x13" "\x12" "Oh, how I miss the ranch..." "\xBF" "", NULL);
