    EZTR_Basic_ReplaceText(0x0930, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x68" "Mmm, I'll give you " "\x01" "one " "\x00" "free sample," "\x11" "so try planting it in some " "\x01" "soft" "\x11" "soil" "\x00" ". You can always buy more." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0931, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0932, 0x00, 0x00, 0xFE, 0x0933, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x68" "Mmm...So you liked my " "\x01" "Magic" "\x11" "Beans" "\x00" " and came back to buy" "\x11" "more?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0933, 0x06, 0x01, 0xFE, 0xFFFF, 0x000A, 0xFFFF, false, "" "\x1E" "\x69" "\x67" "It's " "\x01" "10 Rupees" "\x00" " for one pod." "\x11" " " "\x11" "\x02" "\xC2" "I'll buy it" "\x11" "No thanks" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0934, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x68" "Mmm...Well, if your mood changes," "\x11" "come back and buy some." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0935, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x68" "Mmm..." "\x11" "You don't have enough " "\x06" "Rupees" "\x00" "." "\xBF" "", NULL);
