    EZTR_Basic_ReplaceText(0x0938, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0960, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x8B" "Wha?" "\x11" "...Who are you?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0961, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x16" "?" "\x11" "Pleased to meet you. I am the" "\x11" "Deku princess." "\x11" "\x12" "Were you, by chance, asked by" "\x11" "that monkey to come save me?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0962, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x8C" "Aha! Just as I suspected!" "\x11" "\x1F" "\x00" "\x0A" "You see, your body smells a little" "\x11" "bit like monkey." "\x11" " " "\x10" "So...the monkey made it back fine" "\x11" "after all. That's good." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0963, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I was worried that when I didn't" "\x11" "come home, my father would think" "\x11" "that monkey had kidnapped me!" "\x11" "\x12" "I was worried that my father" "\x11" "would even go so far as to punish" "\x11" "the poor monkey!" "\x11" "\x12" "\x1E" "\x69" "\x34" "Hoo-hoo-hoo." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0964, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1F" "\x00" "\x0A" "......" "\x11" "\x1F" "\x00" "\x0A" "Don't tell me..." "\x11" "\x1F" "\x00" "\x14" "\x1E" "\x69" "\x35" "\x17" "\x01" "Are you serious" "\x00" "?!?" "\x18" "\x1D" "\x01" "\x53" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0965, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Is father actually doing that?!?" "\x11" "\x1E" "\x69" "\x36" "Yet another hasty decision," "\x11" "father!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0966, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x37" "W-Well, we haven't any time to" "\x11" "lose..." "\x11" "\x13" "\x12" "Quickly, Mr. " "\x16" ", could you" "\x11" "please find something to " "\x01" "carry" "\x00" " me" "\x11" "in so you can take me to the" "\x11" "Deku Palace?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0967, 0x00, 0x00, 0xFE, 0x0968, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x8B" "It's Mr. " "\x16" ", correct?" "\x11" "You, sir, have strange powers," "\x11" "indeed..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0968, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x37" "I don't mind tight places, so surely" "\x11" "you have something you can put" "\x11" "me in to " "\x01" "carry" "\x00" " me..." "\x11" "\x12" "If you have anything at all, then," "\x11" "by all means, take it out and use" "\x11" "it right here!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0969, 0x00, 0x00, 0x5F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x37" "Hwh-Hwhy are you hwaiting?" "\x11" "Mr. " "\x01" "\x16" "\x00" "!" "\x11" "\x13" "\x12" "Huh-Hurry! Ho-Hopen this " "\x01" "bottle" "\x11" "\x00" "and release me right hwh-hwhere" "\x11" "my father is standing." "\x1C" "\x00" "\x1E" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x096A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x36" "H-Hufff-huhhh!" "\x11" "\x17" "Foolish father!!!" "\x18" "\x1C" "\x00" "\x14" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x096B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "WHAT are you doing?!?" "\x11" "\x1E" "\x39" "\xA7" "Let that monkey go this instant!!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x096C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x8B" "Oh, Mr. Monkey, I am truly sorry." "\x11" "Father does such rash things" "\x11" "when he's worried about me." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x096D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x8C" "Why yes, thanks to" "\x11" "Mr. " "\x16" " here." "\x11" "I am very, truly grateful." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x096E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "As a symbol of our gratitude, our" "\x11" "butler has prepared a little" "\x11" "something for you." "\x11" "Please accept it." "\x10" "You'll find it in the shrine that" "\x11" "will be to your " "\x01" "right " "\x00" "when you" "\x11" "leave the palace." "\xBF" "", NULL);
