    EZTR_Basic_ReplaceText(0x0971, 0x00, 0x10, 0x5F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x37" "Ungh! Mr. " "\x01" "\x16" "\x00" "!" "\x11" "There's nuh-no time to lose!" "\x11" "Huh-Hurry! Take me to the palace!" "\xBF" "", NULL);
