    EZTR_Basic_ReplaceText(0x0C20, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x5E" "\x17" "Oh!" "\x18" " " "\x1F" "\x00" "\x14" "Welcome to the Mountain" "\x11" "Smithy, where we take our time to" "\x11" "make a good point. I am " "\x01" "Zubora" "\x00" "," "\x11" "the owner. Pleased to meet you." "\x19" "\xBF" "", NULL);
