    EZTR_Basic_ReplaceText(0x0C23, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That huge fellow is my assistant," "\x11" "Gabora. He's all brawn and about" "\x11" "as smart as a Deku Stick." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C24, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Say...Did you come to have your" "\x11" "sword sharpened?" "\x19" "\xBF" "", NULL);
