    EZTR_Basic_ReplaceText(0x0C2B, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x5D" "\x17" "Don't act like you know what" "\x11" "you're talking about, you Deku" "\x11" "Stick!" "\x18" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C2C, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, he believes a rumor that says" "\x11" "long ago there were hot springs " "\x11" "somewhere in the mountains near" "\x11" "here." "\x10" "Bah! I don't believe such rubbish." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C2D, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x66" "Ugoh-oh!" "\x11" "Ugoh ugo ugo?" "\x19" "\xBF" "", NULL);
