    EZTR_Basic_ReplaceText(0x0C33, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh!" "\x11" "You've done me a great favor!" "\x11" "\x1F" "\x00" "\x0A" "\x17" "Now, then" "\x18" "..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C34, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "This hearth can finally go to work" "\x11" "for me!" "\x18" "\x11" "\x1F" "\x00" "\x14" "Heh-heh-heh-heh..." "\x11" "Thanks." "\xE0" "\xBF" "", NULL);
