    EZTR_Basic_ReplaceText(0x0C3C, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, really? Then it can't really be" "\x11" "helped. Drop by again sometime." "\x11" "\x13" "\x12" "Gabora, forget about the coffee!!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C3D, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This is a secret, but I'll let you in" "\x11" "on it...If you bring me some " "\x01" "gold" "\x11" "dust" "\x00" ", I can forge you the" "\x11" "\x01" "strongest of swords" "\x00" "..." "\x10" "It'll never lose its edge. It's the" "\x11" "strongest. The strongest..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C3E, 0x06, 0x31, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Reforge your sword?" "\x11" "\x02" " " "\x11" "\xC2" "Yes" "\x11" "No thanks" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C3F, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Huh? You don't have " "\x06" "100 Rupees" "\x00" "?" "\x19" "\xBF" "", NULL);
