    EZTR_Basic_ReplaceText(0x0C41, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "And we just got the ice melted" "\x11" "off the hearth and everything..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C42, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Thanks for dropping in. Now then," "\x11" "I'm straight off to work!" "\x11" "\x13" "\x12" "Come back " "\x01" "tomorrow morning" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C43, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x66" "Ugoh ugo ugo!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C44, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Your sword will be ready " "\x01" "tomorrow" "\x11" "morning" "\x00" ". We'll take good care of" "\x11" "it, so don't worry." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C45, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, now that's a mean joke. Your" "\x11" "sword has already been reforged" "\x11" "into a " "\x01" "Razor Sword" "\x00" "!" "\x11" "\x12" "Unless..." "\x11" "Do you want me to make your" "\x11" "sword stronger?" "\x11" "\x12" "To do that, I'll need " "\x01" "gold dust" "\x00" "." "\x11" "Do you have any?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C46, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Why, if it isn't " "\x01" "gold dust" "\x00" "! And it's" "\x11" "even top quality!!!" "\x11" "\x13" "\x12" "Why, even if I use it to reforge" "\x11" "your sword, there'll still be some" "\x11" "left..." "\x11" "\x12" "All right! Just for you, I'll do this" "\x11" "for free. But don't tell anyone!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C47, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Huh? That's not " "\x01" "gold dust" "\x00" "." "\x11" "\x13" "\x13" "\x12" "...You can't get your hands on it" "\x11" "that easily, you know!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C48, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x66" "Ugoh-ugo-ugo!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C49, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What? What?!? You say that" "\x11" "\x01" "gold dust" "\x00" " is the prize for winning" "\x11" "the " "\x01" "Patriarch's Race" "\x00" " that's held by" "\x11" "the Gorons every spring?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C4A, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What if you tried entering that?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C4B, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "To make your sword any stronger," "\x11" "I'll need " "\x01" "gold dust" "\x00" ", which just so" "\x11" "happens to be first prize at the" "\x11" "Goron racetrack." "\x10" "If I can just get some gold dust..." "\x11" "and this is just between us...I can" "\x11" "make you the " "\x01" "strongest of" "\x11" "swords" "\x00" ". The strongest..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C4C, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey! Hey! Take it easy!" "\x11" "Your sword is already as strong" "\x11" "as I can make it!" "\x11" "\x12" "It's impossible to make it any" "\x11" "stronger. It doesn't matter how" "\x11" "much gold dust you pack in" "\x11" "there!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C4D, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But..." "\x11" "If you have gold dust, I'll buy it" "\x11" "off you for " "\x06" "40 Rupees" "\x00" "." "\x11" "How about it?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C4E, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Huh? " "\x1F" "\x00" "\x0A" "Look, I'm working on" "\x11" "strengthening your sword. I'm" "\x11" "busy, so don't bother me." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C4F, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Grrr...You're persistent..." "\x11" "I can't focus on my work! Just" "\x11" "wait until morning!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C50, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I kept you waiting..." "\x11" "But it's done! See?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C51, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Now keep in mind that after" "\x11" "you've used this " "\x01" "100 times" "\x00" ", the" "\x11" "blade will lose its edge and will" "\x11" "return to its " "\x01" "original sharpness" "\x00" "." "\x10" "Now here's a secret...If you bring" "\x11" "me " "\x01" "gold dust" "\x00" " before this sword" "\x11" "loses its " "\x01" "edge" "\x00" ", I'll be able to make" "\x11" "it the " "\x01" "strongest sword " "\x00" "around." "\x10" "You got that? " "\x01" "Gold dust" "\x00" "!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C52, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x65" "Ugoh!" "\x11" "Ugoh ugo ugo!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C53, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "There it is. We can't make a" "\x11" "sword stronger than that." "\x11" "\x13" "\x12" "No matter how many times you" "\x11" "use it, it will never lose its edge." "\x11" "Try it." "\x11" "\x12" "Oh, I used up most of the " "\x01" "gold" "\x11" "dust" "\x00" ". Just a tiny bit was left, so" "\x11" "I got rid of it for you." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C54, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x65" "Ugo-oh!" "\x11" "Ugoh ugo ugo!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C55, 0x00, 0x00, 0xFE, 0xFFFF, 0x0028, 0xFFFF, false, "" "Thanks for dropping in!" "\x11" "You got a great deal." "\x19" "\xBF" "", NULL);
