    EZTR_Basic_ReplaceText(0x0C57, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What? You're telling me that's" "\x11" "not enough? No way. That's the" "\x11" "going price. The going price!" "\x11" "\x12" "No one else will buy it for this" "\x11" "much..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C58, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "So, come on...Will you sell it for" "\x11" "\x06" "40 Rupees" "\x00" "?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C80, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xBB" "I'm the Goron who sells the" "\x11" "\x01" "Powder Keg" "\x00" ", the most famous" "\x11" "product of the Gorons." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C81, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x38" "\xFC" "Want a " "\x01" "Powder Keg" "\x00" "?" "\x11" "Powder kegs explode with powerful" "\x11" "blasts and are very dangerous..." "\x11" "\x12" "Until I have tested you to see if" "\x11" "you can use them properly, I can't" "\x11" "let you use any on your own." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C82, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Will you give it a try?" "\x11" " " "\x11" "\x02" "\xC2" "Yes" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C83, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x38" "\xFC" "If you can " "\x01" "destroy" "\x00" " the boulder" "\x11" "that blocks the entrance to the" "\x11" "\x01" "Goron Racetrack" "\x00" " near here..." "\x11" "\x12" "using the " "\x01" "Powder Keg " "\x00" "I'm about" "\x11" "to give you, then I'll approve you" "\x11" "to carry them." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C84, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xBB" "When the " "\x01" "Powder Keg " "\x00" "begins " "\x11" "ticking" "\x01" " faster" "\x00" ", it means that it's" "\x11" "about to explode." "\x11" "\x12" "Try to " "\x01" "blow up" "\x00" " the " "\x01" "boulder" "\x11" "\x00" "blocking the " "\x01" "Goron Racetrack" "\x11" "\x00" "entrance without the " "\x01" "Powder Keg" "\x11" "\x00" "exploding on the way." "\x10" "There's a " "\x01" "sign " "\x00" "near the racetrack," "\x11" "so keep an eye out for it. When" "\x11" "you've finished, come see me." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C85, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xBB" "Come back if you change your" "\x11" "mind." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C86, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\x04" "It looks like you managed to" "\x11" "succeed! Knowing your skills, I" "\x11" "feel fine letting you handle Powder" "\x11" "Kegs on your own." "\x10" "It was bad of me to put you" "\x11" "through such a dangerous test. I" "\x11" "want you to take this as my" "\x11" "apology." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C87, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xBB" "\x01" "Powder Kegs" "\x00" " are very" "\x11" "volatile, so you can carry only " "\x01" "one" "\x11" "\x00" "at a time." "\x11" "\x12" "If you shoot them with an " "\x01" "arrow" "\x00" "," "\x11" "they'll " "\x01" "explode " "\x00" "as soon as they're" "\x11" "hit, so be careful." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C88, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x38" "\xFC" "You failed?" "\x11" "In that case, I can't approve you" "\x11" "to use Powder Kegs." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C89, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Will you take the challenge again?" "\x11" " " "\x11" "\x02" "\xC2" "Yes" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0C8A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xBB" "If you change your mind, see me." "\xBF" "", NULL);
