    EZTR_Basic_ReplaceText(0x0E7B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Now that it's nice and warm out," "\x11" "I'm much, much better." "\x11" "\x13" "\x12" "Even if my daddy isn't right beside" "\x11" "me, I won't be selfish and cry." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E7C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "So...now that spring has come, the" "\x11" "Goron Races should be starting" "\x11" "soon." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E7D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But..." "\x15" "\xBF" "", NULL);
