    EZTR_Basic_ReplaceText(0x0E7F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\x18" "And spring's just started, too..." "\x11" "I was so excited...but there's" "\x11" "nothing I can do..." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E80, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "I hate it!" "\x18" " " "\x17" "I hate it!" "\x18" "\x11" "\x17" "I wanna see it!" "\x18" "\x11" "\x17" "I wanna see it!" "\x18" "\x11" "I wanna see the race!" "\xBF" "", NULL);
