    EZTR_Basic_ReplaceText(0x0E82, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC9" "Did you come to play?" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E83, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you can, you should go see the" "\x11" "Goron races that are gonna be" "\x11" "held on the other side of this" "\x11" "mountain." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E84, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC8" "Way to go, Darmi!" "\x11" "That was cooool!" "\x11" "\x13" "\x12" "C'mon! If we don't hurry, the race" "\x11" "will start. C'mon! Hurry!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E85, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC8" "The Goron Races that honor the" "\x11" "coming of spring are about to" "\x11" "begin." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E86, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It's a really, really cool race, so" "\x11" "you should watch it." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E87, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Once you see these Goron races," "\x11" "you'll wish you were born a Goron." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E88, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC9" "Ah! Darmi!" "\x11" "I've been waiting for you." "\x11" "\x13" "\x12" "See, everyone's restless 'cause" "\x11" "they can't wait to enter. You're" "\x11" "gonna enter, aren't you?" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E89, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You're gonna enter aren't you?" "\x11" " " "\x11" "\x02" "\xC2" "Yep" "\x11" "Nope" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E8A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...You used to like racing more" "\x11" "than you liked gobbling up a third" "\x11" "helping of rock sirloin..." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E8B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\x18" "The Darmi I know would never" "\x11" "back out of a race..." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E8C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I hate it!" "\x11" "I wanna watch you race!" "\x11" "\x17" "I wanna!" "\x18" " " "\x17" "I wanna!" "\x18" " " "\x17" "I wanna!" "\x18" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E8D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "..." "\x1E" "\x3A" "\xC8" "You really do want to race." "\x11" "I know you do." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E8E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC8" "You have to! I want to show" "\x11" "everyone how Darmi races!" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E8F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If your " "\x02" "magic power " "\x00" "runs low," "\x11" "charge it up with the " "\x02" "green jars" "\x11" "\x00" "on the course." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E90, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC8" "That was great!" "\x11" "I knew you were the fastest" "\x11" "Goron, Darmi!" "\x11" "\x12" "I was sure you'd get first place!" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E91, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This is from daddy..." "\x11" "It's the prize." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E92, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I wanna be just like you--quick!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E93, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...You're just a little stiff because" "\x11" "winter was so long." "\x11" "\x13" "\x12" "You're not really like this." "\x11" "\x13" "\x13" "\x12" "Remember how good you really" "\x11" "are, then enter the races again." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E94, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, but if you don't have an" "\x11" "empty bottle to keep the prize in," "\x11" "you can't enter..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E95, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x48" "\x4E" "Everyone, one entrant made a" "\x11" "false start, so we must restart" "\x11" "the race." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E97, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Can you hear me, Darmi? Umm..." "\x11" "I'm sorry, but there's no way you" "\x11" "can win now..." "\x11" "\x12" "Do you want to keep racing" "\x11" "anyway?" "\x11" "\x02" "\xC2" "Of course!" "\x11" "No..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E98, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC8" "C'mon...Enter the race." "\x11" "I want to show everybody how" "\x11" "fast you are." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0E99, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You did it!" "\x11" "Thanks a lot!" "\x11" "\x13" "\x12" "I'm going right in. I'll be waiting" "\x11" "for you, so you have to come" "\x11" "see it!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FA0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x48" "They're late!" "\x11" "What are those Zoras doing?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FA1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x49" "Hmm? What is it, boy?" "\x11" "Did you also come to watch the" "\x11" "Zora eggs hatch?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FA2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm excited about it, too, but" "\x11" "those important eggs haven't" "\x11" "arrived yet..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FA3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It takes about one to three days" "\x11" "from the time Zora eggs are laid" "\x11" "for them to hatch." "\x11" "\x12" "But if they aren't kept in this" "\x11" "\x01" "aquarium" "\x00" " until then...they may die." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FA4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The reason for this is that the" "\x11" "recent abnormal weather has" "\x11" "caused the ocean temperature to" "\x11" "rise in this region." "\x10" "\x01" "Zora eggs " "\x00" "are very sensitive to" "\x11" "changes in the temperature." "\x11" "\x13" "The only way the eggs can hatch" "\x10" "is if they're placed in this" "\x11" "\x01" "aquarium water" "\x00" ", which I set aside" "\x11" "for them long ago." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FA5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x48" "The Zoras are well aware of" "\x11" "this, but they're still late." "\x11" "I wonder if something has" "\x11" "happened at " "\x01" "Zora Hall" "\x00" "?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FA6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x48" "They're late!" "\x11" "What are those Zoras doing?" "\x11" "If they don't hurry, the eggs will" "\x11" "die." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FA7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This is a problem. Zora eggs won't" "\x11" "hatch unless " "\x01" "all eggs" "\x00" " that were" "\x11" "laid at the same time are brought" "\x11" "\x01" "together" "\x00" "." "\x10" "What are those Zoras doing?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FA8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x49" "What are you doing here? You" "\x11" "look a little out of place at the" "\x11" "ocean, don't you think?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FA9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The seas around here are too" "\x11" "warm and aren't suitable for you" "\x11" "to splash around in." "\x11" "\x12" "If you don't have any business" "\x11" "here, then be on your way." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FAA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "These seas are too warm for you" "\x11" "to splash around in. If you haven't" "\x11" "any business here, then be on" "\x11" "your way." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FAB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "And besides, the more I think" "\x11" "about it, the funnier it looks" "\x11" "seeing a fellow like you at the" "\x11" "ocean." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FAC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x49" "What are you doing? Don't you at" "\x11" "least shut your mouth when you're" "\x11" "listening to people?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FAD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The seas around here are too" "\x11" "warm and aren't suitable for you" "\x11" "to splash around in." "\x11" "\x12" "If you don't have any business" "\x11" "here, then be on your way." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FAE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "These seas are too warm to" "\x11" "splash around in. If you haven't" "\x11" "any business here, then be on" "\x11" "your way." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FAF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Are you really getting what I'm" "\x11" "saying to you when you just stand" "\x11" "there with your mouth wide open?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FB0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What happened to the rest of the" "\x11" "eggs? The eggs can't hatch if" "\x11" "they aren't all together." "\x11" "\x12" "Hurry! Find the rest of the eggs" "\x11" "and put them in the aquarium." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FB1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, you finally came? I've been" "\x11" "waiting for you. What about the" "\x11" "eggs?" "\x11" "\x12" "I heard there is a total of " "\x01" "seven" "\x00" "..." "\x11" "Hurry! Put them in that " "\x01" "aquarium" "\x00" "." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FB2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you don't hurry, the eggs will" "\x11" "die. Quickly! Put them in that" "\x11" "aquarium!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FB3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Good. All of the eggs have been" "\x11" "brought together." "\x11" "...It's going to start. Quick! Come" "\x11" "to the front of the aquarium!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FB4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x4A" "L-look at this! What does this" "\x11" "mean...What in the world could" "\x11" "this mean?" "\x11" "\x12" "...I've got it!" "\x11" "\x13" "\x13" "\x12" "Don't you understand? The way" "\x11" "these Zora children have lined" "\x11" "up...It means..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FB5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You...Don't you have some kind of" "\x11" "\x01" "instrument" "\x00" "?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FB6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "......" "\x1F" "\x00" "\x14" "\x11" "Nothing. Not a thing. Could it be" "\x11" "you're using the wrong" "\x11" "instrument?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FB7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x4A" "That! Yes, it's that instrument!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FB8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hmm..." "\x11" "If these Zoras were born to teach" "\x11" "this song, then hurry!" "\x11" "\x12" "You must play this" "\x01" " song " "\x00" "for the" "\x11" "Zora who laid these eggs!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FB9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I will take good care of the Zora" "\x11" "children. You go find the " "\x01" "Zora" "\x11" "who laid these eggs" "\x00" "! Quickly!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FBA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...This is a very strange thing." "\x11" "\x13" "\x13" "\x12" "If Zora children can teach music," "\x11" "then the Zora still hold many" "\x11" "mysteries." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FBB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What happened?" "\x11" "Just what kind of song was that?" "\x11" "\x13" "\x12" "You must know something, don't" "\x11" "you?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FBC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I don't understand what happened," "\x11" "but it seems the ocean has" "\x11" "reclaimed its serenity." "\x11" "\x12" "Could this somehow be related to" "\x11" "that song? You know something," "\x11" "don't you?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FBD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The ocean's temperature has" "\x11" "returned to normal. Did you come" "\x11" "here to splash around in the sea?" "\x11" "\x12" "If you drown trying to swim with" "\x11" "a big ol' body like that, don't" "\x11" "blame me!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FBE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The ocean's temperature has" "\x11" "returned to normal. Did you come" "\x11" "here to splash around in the sea?" "\x11" "\x12" "If you try swimming with that" "\x11" "puny body, you'll be sorry!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0FBF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If they don't hurry, the eggs will" "\x11" "soon die. What could the Zoras be" "\x11" "doing?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1004, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x73" "Unghhh..." "\x11" "\x1F" "\x00" "\x0A" "Somebody..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1005, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x72" "Unghh..." "\x11" "\x1F" "\x00" "\x0A" "Please..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1006, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x73" "G-gu-hu..." "\x11" "\x1F" "\x00" "\x0A" "Get me..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1007, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1F" "\x00" "\x0A" "\x1E" "\x69" "\x72" "...to shore..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1008, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x73" "Uuungh...I am " "\x01" "Mikau" "\x00" " of the Zora" "\x11" "people..." "\x1F" "\x00" "\x0A" "...guitarist in the " "\x01" "Zora" "\x11" "band" "\x00" "..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1009, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x72" "I think this is it for me..." "\x11" "My final " "\x1F" "\x00" "\x0A" "message..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x100A, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x73" "...Will you listen to it?" "\x11" " " "\x11" "\x02" "\xC2" "I'll listen" "\x11" "I won't listen" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x100B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1F" "\x00" "\x0A" "\x17" "One!" "\x18" " " "\x1F" "\x00" "\x0A" "\x17" "Two!" "\x18" " " "\x1F" "\x00" "\x0A" "\x17" "Three!!!" "\x18" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x100C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x74" "Oh, baby, baby, listen to me!" "\x11" "The carnival's beginning soon." "\x11" "We're the ones they're waiting to" "\x11" "see." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x100D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x75" "But " "\x01" "that girl" "\x00" ", our vocalist..." "\x11" "She laid some strange " "\x01" "eggs" "\x00" "." "\x11" "And she's lost her voice," "\x11" "You can't hear what she says." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x100E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x74" "Whoa-oh! In " "\x01" "Great Bay" "\x00" " now" "\x11" "somethin' is a-happenin'." "\x11" "\x1F" "\x00" "\x0A" "\x17" "Is it now?" "\x18" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x100F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh! " "\x1E" "\x69" "\x75" "Baby, listen to me." "\x11" "I don't wanna beg." "\x11" "\x01" "Gerudo Pirates" "\x00" "!" "\x11" "They stole that girl's eggs." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1010, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x74" "I went to stop the Gerudo Pirates," "\x11" "then pow and bam!" "\x11" "I got knocked down," "\x11" "and here I am!" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1011, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x75" "Baby! If I die like this..." "\x11" "Even if I die..." "\x11" "It won't be in peace..." "\x11" "\x1F" "\x00" "\x0A" "\x17" "That's for suuure!" "\x18" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1012, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x74" "Somebody, please rescue her eggs" "\x11" "before the pirates take their toll." "\x11" "Oh, somebody, somebody," "\x11" "please " "\x01" "heal my soul" "\x00" "." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1013, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That's all..." "\x11" "\x1F" "\x00" "\x0A" "\x1E" "\x69" "\x76" "\x17" "Thank you!" "\x18" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1014, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x72" "Gugh-hunh..." "\x11" "M-my eyes...Everything's all hazy..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1015, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x73" "Soon, I'll be just another wave in" "\x11" "the ocean...destined to disappear." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1016, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x74" "Oh, yeah! That hot sound shoots" "\x11" "right to my heart." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1017, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Carve my farewell song on my" "\x11" "grave..." "\x11" "\x1F" "\x00" "\x0A" "I'm depending on you to help that" "\x11" "singer girl..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1018, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Herein lies Mikau, the legendary" "\x11" "guitarist of the Zora tribe. He is" "\x11" "to be remembered in song, and his" "\x11" "lyrics are written here." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1019, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Will you try to sing Mikau's" "\x11" "lyrics?" "\x11" "\x13" "\x12" " " "\x11" "\x02" "\xC3" "1. We the Zora" "\x11" "2. Zora Fight Song" "\x11" "I won't sing" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x101A, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x76" "Sharp fins are the mark of the" "\x11" "Zora. We " "\x01" "swim" "\x00" ", speeding through" "\x11" "the seas with " "\xB0" " and " "\xBB" "." "\x11" "\x12" "If " "\xB4" " is pressed when swimming," "\x11" "a shield is produced to deflect" "\x11" "enemies." "\x11" "(Spoken) If you have magic." "\x10" "We can even dive by pressing " "\xB1" "!" "\x11" "Oh-oh...We the Zora." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x101B, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x76" "For my punch of anger, hit" "\x11" "\xB1" ". Press " "\xB1" " repeatedly for a" "\x11" "flurry of attacks! Yeah, yeah." "\x11" "\x12" "For my deadly move, press and" "\x11" "hold " "\xB1" ". Now release! It's the" "\x11" "final blow. My double cutters!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x101C, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Lulu's Diary" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x101D, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It has been two days since I have" "\x11" "lost my voice." "\x11" "\x13" "\x12" "I don't want Mikau to know, so I" "\x11" "talked to Evan about it." "\x11" "\x13" "\x12" "He recommended that I take the" "\x11" "eggs to the Marine Research Lab" "\x11" "to have them checked." "\x11" "\x12" "I think I will take them right" "\x11" "away." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x101E, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Such a terrible thing has happened" "\x11" "today that I don't even know" "\x11" "where to begin writing." "\x11" "\x12" "I heard a sound late at night, and" "\x11" "when I opened my eyes, I saw" "\x11" "strangers in my room." "\x11" "\x12" "I tried to fight, but they were" "\x11" "able to steal my precious eggs." "\x11" "\x13" "\x12" "It seems I lost consciousness" "\x11" "after that." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x101F, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Today, I told everything to Mikau," "\x11" "the one person whom I didn't" "\x11" "want to know about it." "\x11" "\x12" "At first, I was too embarrassed" "\x11" "and too sad to do anything." "\x11" "\x13" "\x12" "And with the words that Mikau" "\x11" "said at that moment, I felt that" "\x11" "all hope had been lost." "\x11" "\x12" "But please, Mikau, I'm begging you," "\x11" "don't do anything rash." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1020, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "........." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1021, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That sad face is trying to tell you" "\x11" "something." "\x11" "...You can see it in her" "\x11" "expression!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1022, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Mikau, what's going on?" "\x11" "\x13" "\x13" "\x12" "And my voice..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1023, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What happened to me?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1024, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Who are you?" "\x11" "Mikau...Where's Mikau?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1025, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Mm...Mm...Yeeeaaawn!" "\x11" "I slept quite well!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1026, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I just realized this when I opened" "\x11" "my eyes. The passing of days is" "\x11" "quite quick. Isn't it, Lulu?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1027, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Yes, Lulu. It's nothing to be" "\x11" "surprised at." "\x11" "\x13" "\x12" "Although my eyes were closed in" "\x11" "sleep, I still see everything that" "\x11" "occurs in this ocean..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1028, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...Hmm." "\x11" "It seems Lulu is confused." "\x11" "Regrettably, there is no time for" "\x11" "idle conversation." "\x10" "Now then, proud Zora warrior..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1029, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The open seas of Great Bay have" "\x11" "need of your might." "\x11" "\x13" "\x12" "Quickly. Climb onto my back." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x102A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Why so slow?" "\x11" "Hurry up and fire your " "\x01" "hookshot" "\x11" "\x00" "into the palm " "\x01" "tree" "\x00" " on my back," "\x11" "\x16" "." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x102B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Heh, heh, heh." "\x11" "Of course I know your name." "\x11" "Didn't I say that all is seen by" "\x11" "me?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x102C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You seem to be having a bit of" "\x11" "trouble..." "\x11" "\x13" "\x12" "Are you still not used to your" "\x11" "Zora body?" "\x11" "\x13" "\x12" "Perhaps it would be quicker to" "\x11" "give up." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x102D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you are once again ready to" "\x11" "depart, then climb onto my back." "\x11" "\x13" "\x12" "Ready, " "\x16" "?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x102E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What's wrong?" "\x11" "Returning to shore?" "\x11" "\x13" "\x12" "Hyeh, hyeh." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x102F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It is not shameful to retreat. That" "\x11" "in and of itself is a strategy." "\x11" "\x13" "\x12" "All right. Climb onto my back." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1030, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Now I can continue resting in" "\x11" "peace. I too must abide the laws" "\x11" "of ancient times and again merely" "\x11" "watch from my deep slumber." "\x10" "But the evil that haunts this land" "\x11" "has not completely vanished," "\x11" "\x16" ". I shall depart after" "\x11" "enjoying Lulu's voice a bit longer." "\x10" "I think the gods can permit that." "\x11" "Hyeh, hyeh, hyeh." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1031, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Pleased to meet you. I'm Lulu." "\x11" "\x13" "\x13" "\x12" "Please come to our concert in" "\x11" "town." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1032, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I guess being able to sing is a" "\x11" "wonderful thing, after all..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1033, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Mikau!" "\x11" "You came back safely!" "\x18" "\x11" "\x13" "\x12" "That's good..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1034, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I was surprised when my voice" "\x11" "turned that lonely island into a " "\x11" "turtle... " "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1035, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But that song you played for" "\x11" "me...My mother used to sing it" "\x11" "often...long ago..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1036, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Those eggs were laid to remind me" "\x11" "of that." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1037, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That song was from when I was a" "\x11" "very young child, so I had" "\x11" "forgotten it..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1038, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I've put you through some horrible" "\x11" "experiences, Mikau." "\x11" "\x13" "\x12" "But I'm all better now!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1039, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, the town's concert is very" "\x11" "soon." "\x11" "\x13" "\x12" "Let's start our rehearsal!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x103A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1F" "\x00" "\x14" "\x17" "One..." "\x18" " " "\x1F" "\x00" "\x14" "\x17" "two..." "\x18" " " "\x1F" "\x00" "\x14" "\x17" "three..." "\x18" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x103B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...Are you going to the temple" "\x11" "again?" "\x11" "\x13" "\x12" "If there is something left to do," "\x11" "then quickly climb onto my back." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x103C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "P--p-please..." "\x11" "My soul..." "\x11" "\x01" "Heal " "\x00" "it..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1068, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You have strange powers," "\x11" "\x16" ". I have a request for" "\x11" "you. Please follow me." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1069, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Here in the depths of Pinnacle" "\x11" "Rock live many dangerous sea" "\x11" "snakes..." "\x11" "\x12" "My friend is trapped here." "\x11" "\x13" "\x13" "\x12" "\x16" ", can you please find a" "\x11" "way to rid the area of all the" "\x01" " sea" "\x11" "snakes" "\x00" " and help my friend?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x106A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Please do this for me. Please" "\x11" "defeat all the vicious sea snakes" "\x11" "and save my friend." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x106B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Please follow me closely without" "\x11" "making any missteps." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x106C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you try to go beyond Pinnacle" "\x11" "Rock, you'll get lost in the murky" "\x11" "water." "\x11" "\x12" "Before you know it, you'll find" "\x11" "yourself back where you started," "\x11" "so be careful." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x106D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Thank you, " "\x16" "." "\x11" "This is a symbol of my deepest" "\x11" "gratitude." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x106E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Help me..." "\x11" "Please, take me back to the" "\x11" "waters near Pinnacle Rock..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x106F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x4C" "Are you interested in that fish?" "\x11" "\x13" "\x13" "\x12" "It's a rare fish, isn't it?" "\x11" "It's called a sea horse." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1070, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I caught it swimming around here." "\x11" "Just off of Pinnacle Rock." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1071, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Since it's rare, I was thinking of" "\x11" "selling it at the town carnival," "\x11" "which should be starting soon." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1072, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you want, I'll give it to you." "\x11" "\x13" "\x13" "\x12" "On one condition..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1073, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Do you have a " "\x01" "pictograph" "\x00" " of the" "\x11" "\x01" "female pirates" "\x00" "?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1074, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you want that sea horse, bring" "\x11" "me a " "\x01" "pictograph" "\x00" " of a " "\x01" "female" "\x11" "pirate" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1075, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x4D" "Oh! That's my " "\x01" "hookshot " "\x00" "that the" "\x11" "pirates stole!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1076, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...If you have it, then that means" "\x11" "you've been to the " "\x01" "Pirates'" "\x11" "Fortress" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1077, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "In that case, you've got one, don't" "\x11" "you? Don't hide it!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1078, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x60" "What's this? I guess you don't" "\x11" "have one after all." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1079, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Technically, I do have a " "\x01" "pictograph" "\x11" "\x00" "of a " "\x01" "female pirate" "\x00" ", but it's all" "\x11" "blurry and it's not that great..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x107A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The all-important face...I can't see" "\x11" "it very well!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x107B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x4D" "Oh! That's it! That's it!" "\x11" "I had a picture like that." "\x11" "\x13" "\x12" "Well, aren't you a crafty one?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x107C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You'll give that to me, won't you?" "\x11" "\x13" "\x13" "\x12" "In exchange, I'll give you this!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x107D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Thank you." "\x11" "Hurry! Take me back to the" "\x11" "waters near Pinnacle Rock..." "\x1C" "\x00" "\x28" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x107E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "With pictographs, the sepia tone" "\x11" "conveys a lot more emotion than" "\x11" "color. Isn't it great?" "\x11" "\x12" "This picture you gave me is gonna" "\x11" "be one of my treasures." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x107F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x4B" "Well, if it isn't a Zora?" "\x11" "How have things been going" "\x11" "lately?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1080, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Har-harrr!" "\x11" "...Could you be coming to see me" "\x11" "'cause you can't catch any fish?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1081, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x4E" "It's not good out there..." "\x11" "Lately, I've been coming back" "\x11" "empty-handed myself." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1082, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Why, I was almost hoping you" "\x11" "were coming to share with me!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1083, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Sorry, but I don't have any fish to" "\x11" "share with you." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1084, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I've been catching fish in these" "\x11" "seas for 30 years." "\x11" "\x13" "\x12" "When it comes to catching fish," "\x11" "I'm even better than the Zoras." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1085, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x4E" "...That's what I'd like to be saying," "\x11" "anyway." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1086, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Lately, the seawater has gotten" "\x11" "really warm." "\x11" "\x13" "\x12" "It hasn't helped my fishing at all..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1087, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "And what's worse, this water has" "\x11" "gotten murky, so when I ship out," "\x11" "I always lose my way and" "\x11" "somehow end up back at shore." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1088, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We fishermen--and even the" "\x11" "fish--are in a real predicament!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1089, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If the seas don't return to normal" "\x11" "soon..." "\x11" "\x13" "\x12" "The Zoras...and even I...will be" "\x11" "all dried up!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x108A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x4B" "Heh-heh! Isn't she pretty?" "\x11" "\x13" "\x13" "\x12" "But, you know..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x108B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Those female pirates are so" "\x11" "frightening, they could scare a" "\x11" "crying baby into silence..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x108C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "See, it was long ago when I used" "\x11" "to use this thing called a" "\x11" "hookshot to catch fish off the" "\x11" "coast..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x108D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But I was attacked by these" "\x11" "pirates, and they took it away" "\x11" "with them." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x108E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "They say..." "\x11" "it's a legendary treasure.." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x108F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "And I just happened to swipe it" "\x11" "from the bottom of the sea, so I" "\x11" "hold no grudge against 'em." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1090, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It may be a treasure resting" "\x11" "somewhere in the Pirates' Fortress" "\x11" "at the edge of this coast." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1091, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The security at the Pirates'" "\x11" "Fortress is tight. Sneaking in is" "\x11" "no easy task." "\x11" "\x12" "If you're set on meeting those" "\x11" "beautiful pirates, try going to the" "\x11" "\x01" "valley " "\x00" "on the other side of town!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1092, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I've heard there's a " "\x01" "mask" "\x00" " there" "\x11" "that lets the wearer escape" "\x11" "\x01" "detection" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1093, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Come to think of it, there was a" "\x11" "\x01" "Zora " "\x00" "floating lifelessly out in the" "\x11" "\x01" "bay" "\x00" "..." "\x11" "\x12" "But there's probably no helping him" "\x11" "now..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1094, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, sorry! " "\x01" "Evenings" "\x00" " and the first" "\x11" "thing in the " "\x01" "morning" "\x00" " are my " "\x01" "break" "\x11" "times" "\x00" ". Come back later." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1095, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x4C" "Now that the seas are back to" "\x11" "normal, I've started a little" "\x11" "business aimed at tourists." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1096, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you pay " "\x06" "20 Rupees" "\x00" ", I'll invite" "\x11" "you to a " "\x01" "jumping game" "\x00" " that has a" "\x11" "really " "\x01" "big prize" "\x00" "!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1097, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you're up for it, go to that" "\x11" "island in the " "\x01" "center" "\x00" "." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1098, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x4B" "\x17" "Oh, you're up for it!" "\x18" "\x11" "\x13" "\x13" "\x12" "Now then, I'll explain the rules, so" "\x11" "listen carefully." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1099, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm going to light the " "\x01" "torches" "\x00" " on" "\x11" "each of the surrounding " "\x01" "four" "\x11" "islands " "\x00" "in a particular order." "\x11" "\x12" "\x01" "Jump" "\x00" " to the island that has the" "\x11" "\x01" "lit torch" "\x00" ". If you can jump to it" "\x11" "before the torch goes out, you'll" "\x11" "get " "\x01" "one point" "\x00" "!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x109A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you get " "\x01" "20 or more points" "\x11" "\x00" "within the time limit, you'll get a" "\x11" "big prize! But it'll cost you" "\x11" "\x06" "20 Rupees" "\x00" " for one try." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x109B, 0x00, 0x00, 0xFE, 0xFFFF, 0x0014, 0xFFFF, false, "" "\x1E" "\x69" "\x4B" "How about it? Will you give it a" "\x11" "try?" "\x11" "\x02" "\xC2" "Sure" "\x11" "No thanks" "\xBF" "", NULL);
