    EZTR_Basic_ReplaceText(0x113C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That's my life savings. If I can" "\x11" "buy safety with it, then it's" "\x11" "worth it." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x113D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That's my life savings. If I can" "\x11" "buy safety with it, then it's worth" "\x11" "it." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x113E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I had no idea this place was" "\x11" "here...Perhaps, it just might keep" "\x11" "me safe. I'm just glad I found it." "\xE0" "\xBF" "", NULL);
