    EZTR_Basic_ReplaceText(0x1146, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Only a " "\x01" "little time" "\x00" " left...Oh," "\x11" "Goddess of Time, please save me..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1147, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Huh?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1148, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xA8" "\x17" "Ah! Captain, sir! It's been a long" "\x11" "time since we've seen you!" "\x18" "\x11" "\x13" "\x12" "As you have ordered, sir, we are" "\x11" "investigating the " "\x01" "secrets of this" "\x11" "place" "\x00" "." "\x19" "\xBF" "", NULL);
