    EZTR_Basic_ReplaceText(0x1150, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ahh! " "\x17" "Thank you, sir!" "\x18" "\x11" "\x1F" "\x00" "\x0A" "I hope the information I have" "\x11" "provided will be of assistance to" "\x11" "you, sir." "\x10" "Now, as you ordered, sir, I will" "\x11" "finish the last of my duties." "\xE0" "\xBF" "", NULL);
