    EZTR_Basic_ReplaceText(0x11A5, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\x71" "It takes courage to come thieving" "\x11" "in the Pirates' Fortress!" "\x11" "\x13" "\x12" "I'm going to love doing this to" "\x11" "you!" "\xE0" "\xBF" "", NULL);
