    EZTR_Basic_ReplaceText(0x11A9, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "How unfortunate. You won't be" "\x11" "getting past here!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x11AA, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ugh! Not bad..." "\x11" "But don't think it ends here!" "\xE0" "\xBF" "", NULL);
