    EZTR_Basic_ReplaceText(0x1200, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm not runnin' an inquiry or" "\x11" "anything..." "\x11" "\x13" "\x12" "But, look...If we don't start" "\x11" "rehearsin' real soon, we're not" "\x11" "gonna be ready for the concert." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1201, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What were the other band" "\x11" "members doing?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1202, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You do know that if we don't" "\x11" "start rehearsing, we're not gonna" "\x11" "be ready for the concert, right?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1203, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey...Why don't we forget about" "\x11" "waiting for Evan to write a song" "\x11" "and just write one ourselves?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1204, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you feel up to it, let's have a" "\x11" "little jam session." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1205, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Did you play our song for Evan?" "\x11" "\x1F" "\x00" "\x08" "What did he say?" "\x11" "\x13" "\x12" "Don't tell me..." "\x11" "\x13" "\x13" "\x12" "You didn't forget the song, did" "\x11" "you?" "\x11" "\x02" "\xC2" "Yeah, I did" "\x11" "No, I didn't" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1206, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, in that case, hurry up and" "\x11" "play Evan our song." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1207, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, man. In that case, I guess we" "\x11" "have to have another jam session." "\x11" "Are ya ready?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1208, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6B" "Huh?" "\x11" "You wanna have a jam session?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1209, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Try following this phrase I wrote" "\x11" "on your guitar." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x120A, 0x03, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Here we go..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x120B, 0x03, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6B" "Whoooa..." "\x11" "That's niiiice." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x120C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1F" "\x00" "\x04" "\x17" "I got it!" "\x18" " " "\x1F" "\x00" "\x04" "\x17" "I got it!" "\x18" " " "\x1F" "\x00" "\x04" "\x17" "I got it!" "\x18" "\x11" "\x1F" "\x00" "\x04" "Here I go!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x120D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6B" "That's got a good feel to it! Even" "\x11" "Evan should like this." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x120E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But..." "\x11" "\x13" "\x13" "\x12" "He's so proud...He'd resent the" "\x11" "fact that we wrote somethin' on" "\x11" "our own. I don't think he'd even" "\x11" "let the others try it out." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x120F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Whaddya think we should do?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1210, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "How can we, like, make sure that" "\x11" "Evan doesn't find out that it was" "\x11" "us who wrote this song?" "\x11" "\x12" "Can't you think of anything?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1211, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That melody's bogus, man!" "\x11" "\x13" "\x13" "\x12" "What's wrong? You're not jammin'" "\x11" "like you usually do!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1212, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You wanna stop?" "\x11" " " "\x11" "\x02" "\xC2" "Yeah" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1213, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You in a slump?" "\x11" "Don't worry about it..." "\x11" "\x13" "\x12" "Those were the kind of notes an" "\x11" "amateur would play while tryin' to" "\x11" "figure out the notes as he goes..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1214, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6B" "Once you're back in the groove," "\x11" "we'll write a song that'll knock" "\x11" "Evan off his flippers!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1215, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "When you're in a slump, all ya" "\x11" "can do is go back to your room" "\x11" "and sleep on it." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1216, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That's uncool, man..." "\x11" "What are you tryin' to do, walkin'" "\x11" "into people's rooms like that?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1217, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6B" "Do you wanna have a jam session" "\x11" "with me usin' that instrument?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1218, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Sorry, but try somethin' else." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1219, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x67" "Mikau?" "\x11" "Where've you been? Where've you" "\x11" "been? I was worried." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x121A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The concert in town is coming up," "\x11" "but it seems like all the band" "\x11" "members are in a funk. I betcha" "\x11" "didn't know that, huh?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x121B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Especially Lulu." "\x11" "I haven't heard her voice in a long" "\x11" "time." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x121C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "She's usually in good spirits, too." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x121D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ooh! Ooh! I wonder if this is" "\x11" "related to the ocean turning all" "\x11" "weird..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x121E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x68" "Actually..." "\x11" "I know a little bit of " "\x01" "Lulu's" "\x11" "secret" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x121F, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Do you wanna hear it?" "\x11" " " "\x11" "\x02" "\xC2" "I wanna hear it" "\x11" "Not really" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1220, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "There's a rumor that the ocean is" "\x11" "getting weird 'cause there's" "\x11" "trouble off shore at " "\x01" "Great Bay" "\x11" "Temple" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1221, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "And they say when that happens," "\x11" "something bad will befall the " "\x01" "Zora" "\x11" "descendant" "\x00" " who's been protecting" "\x11" "the temple." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1222, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Do you catch my drift?" "\x11" "\x13" "\x13" "\x12" "And lately, Lulu has been looking" "\x11" "kind of weird. Maybe Lulu's the..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1223, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x67" "Oh, yeah, that's right. There aren't" "\x11" "any secrets between you and Lulu." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1224, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ooh! Ooh!" "\x11" "Don't tell Lulu that I've been" "\x11" "saying stuff about her..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1225, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x68" "Um..." "\x11" "Don't get mad, but I want you to" "\x11" "hear this..." "\x11" "\x12" "I tried to climb up the other" "\x11" "ladder to your practice area, and" "\x11" "it broke. I'm gonna go on a diet" "\x11" "now, so just forgive me, OK?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1226, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x67" "Ooh! Ooh!" "\x11" "How's Lulu?" "\x11" "Is she talking to you?" "\x11" "\x12" "Look..." "\x11" "It's about Lulu's secret..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1227, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x67" "Huh? Who are you?" "\x11" "You can't just come walkin' in" "\x11" "here." "\x11" "\x12" "I don't have a problem, but I think" "\x11" "my roommate might get mad." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1228, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Just follow the rules if you're one" "\x11" "of our fans." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1229, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x68" "This is a problem. You just can't" "\x11" "come in and hang out in our" "\x11" "room!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x122A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x1E" "\x68" "\x45" "Can you read Zoran script?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x122B, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Mikau" "\x11" "My Diary" "\x11" "\x13" "\x12" "Today, Japas and I had a jam" "\x11" "session. He's not good with words," "\x11" "but he writes great riffs." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x122C, 0x03, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Here's what I played:" "\x18" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x122D, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Today, I had Lulu listen to my" "\x11" "session with Japas." "\x11" "\x13" "\x12" "She seemed to like it a lot." "\x11" "Lulu's a pretty great girl," "\x11" "after all." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x122E, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Today, I had another jam session" "\x11" "with Japas." "\x11" "\x13" "\x12" "Evan was in a bad mood 'cause" "\x11" "the two of us are writin' songs on" "\x11" "our own." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x122F, 0x03, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Here's what I played:" "\x18" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1230, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Evan called me over this morning." "\x11" "It was something about Lulu." "\x11" "\x13" "\x12" "He was in a real rush. I wonder" "\x11" "what it could be?" "\x11" "\x13" "\x12" "By the way, it seems my lucky" "\x11" "color this week is " "\x02" "green" "\x00" "." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1231, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Mikau! How was it? Did you get" "\x11" "the eggs back?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1232, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You did it, Mikau!" "\x11" "\x13" "\x13" "\x12" "OK...Take that egg straight to the" "\x11" "professor at the Marine Research" "\x11" "Lab." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1233, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I've already talked to the" "\x11" "professor. Leave the rest up to" "\x11" "him." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1234, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, thank goodness! Lulu's voice" "\x11" "has been brought back to normal!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1235, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I've already talked to the" "\x11" "professor, so after delivering the" "\x11" "eggs, you can leave the rest up" "\x11" "to him." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1236, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "How was it? Did the professor at" "\x11" "the Marine Research Lab figure" "\x11" "out the mystery of the eggs?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1237, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh..." "\x11" "You couldn't do it, after all." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1238, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Have you been to see Lulu out in" "\x11" "back by the ocean?" "\x11" "\x13" "\x12" "Ever since the pirates stole her" "\x11" "eggs, she's just been standing out" "\x11" "there gazing at the sea and" "\x11" "sighing..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1239, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...Mikau!" "\x11" "We need those eggs safe so Lulu" "\x11" "can get her voice back." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x123A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We've grown accustomed to life" "\x11" "in a peaceful sea..." "\x11" "\x13" "\x12" "The only one among the Zora tribe" "\x11" "who is still able to go to blows" "\x11" "with those wild pirates..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x123B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It is you, with the blood of Zoran" "\x11" "heroes flowing within you." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x123C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm still keeping Lulu's problem a" "\x11" "secret from the other band" "\x11" "members." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x123D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "They've all been looking forward to" "\x11" "our Carnival of Time concert." "\x11" "\x13" "\x12" "And I can't tell them it's canceled" "\x11" "'cause Lulu can't sing, can I?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x123E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Anyway, Mikau, did you get an" "\x11" "\x01" "empty bottle " "\x00" "that you can use to" "\x11" "carry the eggs in?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x123F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "One " "\x01" "bottle" "\x00" " can only hold one " "\x01" "egg" "\x00" "," "\x11" "so you can never have too many" "\x11" "\x01" "empty bottles" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1240, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I told you that the " "\x01" "beavers" "\x00" " above" "\x11" "the" "\x01" " waterfall" "\x00" " on the Zora Hall" "\x11" "coast have " "\x01" "empty bottles" "\x00" ", right?" "\x11" "\x12" "If you don't have any yet, Mikau," "\x11" "you should go there before" "\x11" "heading off to the Pirates'" "\x11" "Fortress." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1241, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The Carnival of Time concert is" "\x11" "quickly approaching..." "\x11" "\x13" "\x12" "Hurry up and get those eggs back" "\x11" "from the pirates." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1242, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I already told you the beavers" "\x11" "above the " "\x01" "waterfall" "\x00" " have " "\x01" "empty" "\x11" "bottles" "\x00" ", right?" "\x11" "\x12" "If you don't have any yet, you" "\x11" "should go there before going to" "\x11" "the Pirates' Fortress." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1243, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What is this?" "\x11" "You can't just come into people's" "\x11" "rooms and make yourself at home!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1244, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ahh..." "\x11" "If Lulu's voice doesn't return," "\x11" "I don't know what we can do..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1245, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey!" "\x11" "How did you get in here?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1246, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I shouldn't have to put up with" "\x11" "this...People not associated with" "\x11" "the band aren't allowed in here." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1247, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you want an autograph, we'll be" "\x11" "giving them out at the town's" "\x11" "carnival, so wait until then." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1248, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Were you guys secretly writing a" "\x11" "song behind my back again?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1249, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Isn't songwriting the job of the" "\x11" "bandleader? What, you're not" "\x11" "happy with my songs?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x124A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I heard that song. If you write" "\x11" "any other good songs, I'd like" "\x11" "to hear them." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x124B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Huh?" "\x11" "That song?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x124C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hmmm..." "\x11" "\x1F" "\x00" "\x04" "\x17" "It works," "\x18" " " "\x1F" "\x00" "\x04" "\x17" "it works," "\x18" "\x11" "\x1F" "\x00" "\x04" "\x17" "it works!" "\x18" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x124D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Not bad..." "\x11" "\x1F" "\x00" "\x0A" "That's a pretty good song I just" "\x11" "made up!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x124E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You've got a good sense of" "\x11" "melody! We'll play my new song at" "\x11" "our next show! Take this in" "\x11" "thanks!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x124F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You're not thinking I'm stealing" "\x11" "your song, do you? " "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1250, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you want an autograph, I'll give" "\x11" "you one after our rehearsal." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1251, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What have you been doing? You're" "\x11" "late, Mikau!" "\x11" "\x13" "\x12" "Ooh! Ooh!" "\x11" "Guess what! Lulu's voice..." "\x11" "She's gotten it back!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1252, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hurry up and go see Lulu." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1253, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "And with that, we're all ready." "\x11" "I can't wait for the town's" "\x11" "concert." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1254, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We've kept you waiting! Just a" "\x11" "little bit longer and we'll play our" "\x11" "hot sound for you!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1255, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "You're late, Mikau! Where were" "\x11" "you while you were skippin'" "\x11" "practice?" "\x18" "\x11" "\x12" "\x1F" "\x00" "\x0A" "Lulu's been waiting for you." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1256, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "What were you doing?" "\x18" "\x11" "\x1F" "\x00" "\x14" "Hurry up and go talk to Lulu!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1257, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, Mikau..." "\x11" "\x13" "\x13" "\x12" "That song Evan wrote sounds just" "\x11" "like the one we played at our jam" "\x11" "session, doesn't it?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1258, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I've written a great song, so just" "\x11" "be patient." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1259, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You did great, Mikau." "\x11" "Lulu's voice " "\x1F" "\x00" "\x0A" "has returned." "\x11" "\x13" "\x12" "Well, it looks like Lulu wants to" "\x11" "talk to you, " "\x1F" "\x00" "\x0A" "\x17" "so go see her" "\x11" "now." "\x18" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x125A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, hurry up!" "\x11" "We're about to start rehearsal." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x125B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm glad I got this new song done" "\x11" "in time for the concert." "\x11" "\x13" "\x12" "You did great, Mikau. And even" "\x11" "without any practice." "\x11" "\x13" "\x12" "You really are a musical genius..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x125C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You're an unusual sight to see in" "\x11" "this neck of the water..." "\x11" "\x13" "\x12" "You came to see the Zora band," "\x11" "The Indigo-Go's, didn't you?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x125D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The members of The Indigo-Go's" "\x11" "are in " "\x01" "Zora Hall" "\x00" " up ahead..." "\x11" "\x13" "\x12" "But the entrance is underwater," "\x11" "so if you aren't a good diver, you" "\x11" "probably won't make it in." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x125E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The members of The Indigo-Go's" "\x11" "are up ahead in " "\x01" "Zora Hall" "\x00" "..." "\x11" "\x13" "\x12" "But if you can't dive deep" "\x11" "underwater, you won't get in." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x125F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, aren't you Mikau?" "\x11" "Were you able to get an empty" "\x11" "bottle from the beavers on top of" "\x11" "the" "\x01" " waterfall" "\x00" "?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1260, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Those guys are quick, so it's" "\x11" "pretty tough, isn't it?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1261, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But what do you need an " "\x01" "empty" "\x11" "bottle" "\x00" " for, Mikau?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1262, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Can you " "\x01" "break " "\x00" "all those jars" "\x11" "behind me in one try?" "\x11" "\x13" "\x12" "Among us Zora, there are some" "\x11" "who can." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1263, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you do it, I'll give you" "\x11" "something good." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1264, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Anything's worth a try!" "\x11" "Think it over and give it a shot." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1265, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, Mikau..." "\x11" "You wanna do that thing you used" "\x11" "to always do?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1266, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You just can't play guitar all the" "\x11" "time. You gotta get out and move" "\x11" "your body once in a while." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1267, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Clock Town's carnival is coming" "\x11" "soon and business there is good." "\x11" "That'd be nice...Things here aren't" "\x11" "picking up yet." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1268, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We haven't been able to catch any" "\x11" "fish in the ocean, so we have to" "\x11" "go to town to buy them." "\x11" "\x12" "We never had a need for " "\x06" "Rupees" "\x11" "\x00" "until now." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1269, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I have a shop inside Zora Hall, so" "\x11" "actually I'd like you to go there" "\x11" "and buy a lot of stuff..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x126A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I don't want to sound greedy, but" "\x11" "I need to make money for the" "\x11" "jars." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x126B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We can't fish in the ocean" "\x11" "anymore, so everyone's going into" "\x11" "town to buy them instead." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x126C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But I just can't get used to the" "\x11" "taste of fish from a river." "\x11" "\x13" "\x12" "But a Zora's gotta eat, so there's" "\x11" "no way around it." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x126D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If your band does well with its" "\x11" "concert in town, it'll bring tourists" "\x11" "here and..." "\x11" "\x12" "I won't have to ask for jar money." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x126E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Way to go, Mikau!" "\x11" "\x13" "\x13" "\x12" "You've got a big smirk on your" "\x11" "face..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x126F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, here's " "\x06" "100 Rupees" "\x00" "." "\x11" "\x13" "\x13" "\x12" "Except..." "\x11" "Jar replacement costs " "\x06" "10 Rupees" "\x00" "," "\x11" "so I'll have to deduct that." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1270, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You get " "\x06" "90 Rupees" "\x00" "!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1271, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Take the challenge again sometime." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1272, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Whoa!" "\x11" "There are others besides Zoras" "\x11" "who can do it..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1273, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What's wrong? Have you lost your" "\x11" "touch from playing too much" "\x11" "guitar, Mikau?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1274, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Didn't you used to be able to" "\x11" "break all these pots at once?" "\x11" "\x13" "\x12" "Your motion was all stiff like" "\x11" "someone who's not used to doing" "\x11" "this..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1275, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Sorry, but I have to take" "\x11" "\x06" "10 Rupees" "\x00" " for those broken jars." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1276, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, that's a problem...Don't go" "\x11" "breaking my jars. Those jars" "\x11" "aren't free, you know." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1277, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What? You don't even have" "\x11" "\x06" "10 Rupees" "\x00" "?" "\x11" "\x13" "\x12" "I guess there's nothing I can do..." "\x11" "I'll just have to eat the loss." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1278, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you break them all at once, I'll" "\x11" "give you something good." "\x11" "\x13" "\x12" "Take the challenge again sometime." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1279, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This is the room of Mikau and" "\x11" "Tijo, the guitarist and drummer for" "\x11" "the Zora band, The Indigo-Go's." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x127A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "They don't meet with ordinary" "\x11" "people." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x127B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "No way. If you want to meet" "\x11" "Mikau and Tijo, you'll have to go" "\x11" "through their manager." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x127C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, Mikau..." "\x11" "I haven't seen you in a while." "\x11" "Where have you been?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x127D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, that's right. Evan, your" "\x11" "bandleader, is looking for you." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x127E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Evan came by several times" "\x11" "looking for you. Have you seen" "\x11" "him yet?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x127F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This is the room of Japas, bassist" "\x11" "for the Zora band, The Indigo-Go's." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1280, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm sorry, but he's busy practicing" "\x11" "for the concert, so I can't let you" "\x11" "see him." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1281, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you're not a band member, you" "\x11" "can't go in...Even if you're an" "\x11" "acquaintance." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1282, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Mikau..." "\x11" "Do you need to see Japas?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1283, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You're gonna have another jam" "\x11" "session with him, aren't you?" "\x11" "I can't wait!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1284, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm expecting a cool performance" "\x11" "in your jam session with Japas." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1285, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This is the room of Evan, the" "\x11" "leader of the Zora Band, The" "\x11" "Indigo-Go's." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1286, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "He's a nervous guy, so nobody's" "\x11" "allowed inside unless they're on" "\x11" "official business." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1287, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Unless you have official business," "\x11" "it's impossible to see him until" "\x11" "after the concert." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1288, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ah! Mikau!" "\x11" "What have you been doing this" "\x11" "whole time?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1289, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Evan the bandleader has been" "\x11" "waiting for you for a while now." "\x11" "Hurry! Go in! Go in!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x128A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Stop worrying the bandleader like" "\x11" "you do..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x128B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Shut up! I'm busy." "\x11" "Don't talk to me!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x128C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Shut up. I'm busy right now..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x128D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ah! Mikau!" "\x11" "You caught me!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x128E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Eee...I...uh...er, L-Lulu's been" "\x11" "l-looking kinda weird lately..." "\x11" "I was w-worried..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x128F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It's not like I was s-spying on" "\x11" "her or anything..." "\x11" "\x13" "\x12" "I-I'm not some k-kind of weirdo or" "\x11" "some sorta slimy fish or anything." "\x11" "...Um, yeah." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1290, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Uh...I just r-remembered that I" "\x11" "have somewhere to be...What time" "\x11" "is it? Um, yeah. I hafta be there," "\x11" "like, now. Uhhh...See ya!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1291, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Did you come to see The" "\x11" "Indigo-Go's rehearse, too?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1292, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "No?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1293, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Have you heard of The" "\x11" "Indigo-Go's?" "\x11" "\x02" "\xC2" "Of course" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1294, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I thought so. The Indigo-Go's are" "\x11" "pretty big now, aren't they?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1295, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Their rehearsal is about to begin," "\x11" "so I thought you came to see" "\x11" "them." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1296, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But even though their concert in" "\x11" "town is tomorrow, they still" "\x11" "haven't started rehearsing." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1297, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I wonder what they're doing?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1298, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Huh? You don't know them?" "\x11" "The Indigo-Go's is that popular" "\x11" "band that's going to be doing a" "\x11" "concert in town soon!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1299, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "They've got" "\x01" " Evan" "\x00" ", the keyboard" "\x11" "king, the thumping bass of " "\x01" "Japas" "\x00" "," "\x11" "the cool drum beat of " "\x01" "Tijo" "\x00" "..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x129A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But above all, " "\x01" "Mikau" "\x00" "'s weeping" "\x11" "guitar and the shimmering voice of" "\x11" "\x01" "Lulu " "\x00" "make the best songs!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x129B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ah, you're Mikau, right? Good luck" "\x11" "practicing for the concert!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x129C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm looking forward to your " "\x11" "rehearsal." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x129D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Aren't you going to rehearse?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x129E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Or are you just gonna hit the" "\x11" "stage without any practice?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x129F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hohhh!" "\x11" "That's a real genius guitarist!" "\x11" "So bold!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12A0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The stage lights turned on! The" "\x11" "rehearsal's gotta start soon." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12A1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ahh...Lulu!" "\x11" "Hurry up and show your face on" "\x11" "stage!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12A2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Did you come here to see The" "\x11" "Indigo-Go's 'cause you couldn't" "\x11" "wait for the concert?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12A3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I heard they were having a" "\x11" "rehearsal, and I've been waiting" "\x11" "here ever since." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12A4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But the stage lights aren't even" "\x11" "lit, so it looks like it'll be a while" "\x11" "before rehearsals start." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12A5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I wonder when they're gonna" "\x11" "start? C'mon, I want to see my" "\x11" "Lulu." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12A6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ah! Mikau!" "\x11" "Hey, what's Lulu doing now?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12A7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm so jealous of you! To always" "\x11" "be able to breathe the same air" "\x11" "as Lulu..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12A8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "And you know a side of Lulu that" "\x11" "I don't...You know her private side," "\x11" "don't you?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12A9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That's wonderful. I won't ask you" "\x11" "to introduce me. A pictograph will" "\x11" "do. Show me Lulu's private side." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12AA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Did you by chance bring something" "\x11" "of Lulu's?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12AB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If it's about Lulu, I want to know" "\x11" "everything. I'll take anything...You" "\x11" "know? I'm the consummate fan!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12AC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hmmm...This isn't that great, but" "\x11" "I'll buy it off you anyway." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12AD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Next time, bring me a better shot" "\x11" "that really captures Lulu." "\x11" "If you do that..." "\x11" "I'll do you no wrong." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12AE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh! Lulu's face." "\x11" "It's irresistible!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12AF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Please let me have this!" "\x11" "OK? OK?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12B0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Keep the change." "\x11" "\x13" "\x13" "\x12" "For this kind of pictograph, I'll" "\x11" "take as many as you have, so" "\x11" "bring more!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12B1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, you can't do that. No" "\x11" "climbing up on the rehearsal" "\x11" "stage." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12B2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We're doin' the sound check right" "\x11" "now, so don't make any noise." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12B3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hurry up and get off the stage." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12B4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Mikau, you're just in time. I want" "\x11" "to check the levels on your" "\x11" "guitar." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12B5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Can you play me a note?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12B6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Mikau, can you play me a quick" "\x11" "note?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12B7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ack!" "\x11" "That's a little too loud." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12B8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I guess I'll turn it down a bit..." "\x11" "\x13" "\x13" "\x12" "OK. Thanks, Mikau." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12B9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Huh?" "\x11" "That's a little too quiet..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12BA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I guess I'll turn it up a bit..." "\x11" "\x13" "\x13" "\x12" "OK. Thanks, Mikau." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12BB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Wha? They're off again. That's a" "\x11" "problem..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12BC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Are you free? If you have a sec," "\x11" "could you go light the second" "\x11" "floor's seating lights?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12BD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Unless those are on, the stage" "\x11" "lights won't come on." "\x11" "Thanks." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12BE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Are you the one who turned those" "\x11" "lights on?" "\x11" "\x13" "\x12" "You saved me." "\x11" "Here...Go buy whatever you like!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12BF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "All right...The lights are all good." "\x11" "Now we just have to wait..." "\x11" "But they'll probably go out " "\x11" "again pretty soon..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12C0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What do you want, Mikau?" "\x11" "Are you checking the stage?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12C1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I don't know why, but there's" "\x11" "something wrong with the" "\x11" "lighting..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12C2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The lighting isn't working right." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12C3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Mikau..." "\x11" "How do you like it? The lights are" "\x11" "perfect." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12C4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Now hurry up and do start your" "\x11" "rehearsal before the lights go out." "\x11" "Hurry! Hurry!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12C5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hurry and start your rehearsal" "\x11" "before the lights go out." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12C6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Huh? Here too? This is a problem." "\x11" "Rehearsal hasn't started yet, so I" "\x11" "guess it's OK, but..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12C7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Once rehearsal starts, you'll have" "\x11" "to buy a ticket!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12C8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The Indigo-Go's is a wildly popular" "\x11" "band right now." "\x11" "\x13" "\x12" "If we don't sell tickets to their" "\x11" "rehearsals, too, we'll end up with" "\x11" "tons of people showing up." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12C9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Once the rehearsal starts, you'll" "\x11" "have to buy a ticket. You just" "\x11" "can't go and take a seat." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12CA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oy! Mikau! What's up with the" "\x11" "rehearsal?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12CB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I've been told that rehearsal is" "\x11" "about to begin..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12CC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But the band members are still" "\x11" "shut away in their rooms..." "\x11" "\x13" "\x12" "And Lulu's just hanging around by" "\x11" "that lone island out back." "\x11" "What's going on?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12CD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Is Lulu all right? She was just" "\x11" "staring out at the lone island in" "\x11" "back...She looks kinda strange." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12CE, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Welcome." "\x11" "What are you looking for?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12CF, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We didn't have what you wanted?" "\x19" "\xBF" "", NULL);
