    EZTR_Basic_ReplaceText(0x12D1, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Didn't the big guy's shop have" "\x11" "what you were looking for?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12D2, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Welcome." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12D3, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Did you find something?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12D4, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ah! Mikau." "\x11" "Welcome!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12D5, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You don't quite seem like yourself" "\x11" "today, Mikau." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12D6, 0x06, 0x31, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "View products by moving " "\xBB" " left" "\x11" "or right." "\x11" "\x02" "\xC2" "Speak to shopkeeper" "\x11" "Quit shopping" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12D7, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You came to see The Indigo-Go's," "\x11" "too, didn't you?" "\x11" "I can tell." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12D8, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The celebrities' dressing rooms are" "\x11" "near here. Maybe you can take a" "\x11" "peek..." "\x11" "Just don't get caught." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12D9, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Lately, I've had a hard time even" "\x11" "getting fish in stock, so this is" "\x11" "all I have." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x12DA, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Your band's popularity is amazing." "\x11" "We've had all kinds of people" "\x11" "coming into the shop lately." "\x19" "\xBF" "", NULL);
