    EZTR_Basic_ReplaceText(0x151F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1F" "\x00" "\x0A" "\x1E" "\x3A" "\x39" "Feeble!" "\x11" "\x1F" "\x00" "\x14" "\x1E" "\x3A" "\x89" "\x17" "Feeble!" "\x18" " " "\x17" "Feeble!" "\x18" " " "\x17" "Feeble!" "\x18" " " "\x17" "Feeble!" "\x18" "\x11" "\x1E" "\x3A" "\x89" "\x17" "Feeble!" "\x18" " " "\x17" "Feeble!" "\x18" " " "\x17" "Feeble!" "\x18" " " "\x17" "Feeble!" "\x18" "\x11" "\x1E" "\x3A" "\x89" "\x17" "Feeble!" "\x18" " " "\x17" "Feeble!" "\x18" " " "\x17" "Feeble!" "\x18" " " "\x17" "Feeble!" "\x18" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1520, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\x88" "\x17" "Shut up, already!" "\x18" "\x11" "\x13" "\x13" "\x12" "\x1E" "\x3A" "\x36" "Grrrr!!!" "\x11" "Don't look at me--I was once" "\x11" "called the best swordsman in all" "\x11" "of Ikana..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1521, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\x89" "The greatest swordsman in all of" "\x11" "Ikana?" "\x11" "\x1F" "\x00" "\x0A" "You?" "\x11" "Feeeeeeeeble." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1522, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1F" "\x00" "\x0A" "..." "\x1E" "\x3A" "\x36" "Draw your weapon!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1523, 0x06, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1F" "\x00" "\x0A" "\x1E" "\x3A" "\x39" "Huh?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1524, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\x88" "I'm telling you to draw your" "\x11" "sword!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1525, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "......" "\x11" "\x13" "\x13" "\x12" "\x1E" "\x3A" "\x39" "\x17" "How?" "\x18" "\xBF" "", NULL);
