    EZTR_Basic_ReplaceText(0x152A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It all happened after somebody" "\x11" "thrust open the doors of that" "\x11" "\x01" "Stone Tower" "\x00" "." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x152B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You who bring light into darkness," "\x11" "I am the King of Ikana Kingdom," "\x11" "Igos du Ikana." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x152C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The spellbinding that had been" "\x11" "cast upon us was broken by that" "\x11" "light which you carry." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x152D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "To return true light to this land," "\x11" "you must seal the doors of " "\x01" "Stone" "\x11" "Tower" "\x00" " where the winds of" "\x11" "darkness blow through." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x152E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But Stone Tower is an" "\x11" "impenetrable stronghold. Hundreds" "\x11" "of soldiers from my kingdom would" "\x11" "not even be able to topple it." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x152F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It is far too reckless for one to" "\x11" "take on such a challenge." "\x11" "\x13" "\x12" "...And so..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1530, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I grant to you a " "\x01" "soldier" "\x00" " who has" "\x11" "\x01" "no heart" "\x00" ". One who will not falter" "\x11" "in the darkness." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1531, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This " "\x01" "soldier" "\x00" " who has " "\x01" "no heart " "\x00" "is" "\x11" "your twin image. A shell of" "\x11" "yourself that you will shed when " "\x11" "your song commands it." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1532, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "On my kingdom...shine the light" "\x11" "of justice..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1533, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The darkness in which my" "\x11" "servants live is, after all, fleeting." "\x1A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1534, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "just what kind of thing true" "\x11" "darkness really is." "\x1A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1535, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Wait!" "\x18" "\x11" "\x1F" "\x00" "\x0A" "It is my loss!" "\x11" "Sheathe your weapon..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1536, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I commanded the Ikana Army of" "\x11" "Ikana Kingdom atop the hill. I am" "\x11" "called Skull Keeta." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1537, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Since being shamed by loss in a" "\x11" "battle within my kingdom..." "\x11" "\x13" "\x12" "I have waited here for one to" "\x11" "come and awaken my soul." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1538, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Young swordsman who has" "\x11" "awakened and deftly defeated" "\x11" "me..." "\x11" "\x12" "I shall rely on your power to" "\x11" "fulfill my request." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1539, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I ask you to take my soul, which" "\x11" "rests in the fiercely burning" "\x11" "flame..." "\x11" "\x12" "And convey my words to my men," "\x11" "who, even in death, remain loyal" "\x11" "to me." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x153A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Tell them the war has ended..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x153B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Then I shall be able to drift" "\x11" "quietly into sleep..." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x153C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Captain, sir!" "\x18" "\x11" "\x13" "\x13" "\x12" "May I take leave, sir?" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x153D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xC5" "Yes, sir!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x153E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\x2E" "\x17" "Ohhh! Keeta!" "\x18" "\x11" "\x1F" "\x00" "\x08" "\x17" "Is it not Captain Keeta?!?" "\x18" "\x1A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x153F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...............But you're so..." "\x1A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1540, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I was nearly fooled by what you" "\x11" "have done..." "\x1A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1541, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you could not even catch me," "\x11" "then that must be all the strength" "\x11" "you have." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1542, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...T-Tiny!!!" "\x1A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x157C, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x3B" "Stop it!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x157D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x30" "Who are you?" "\x11" "What are you doing just walking" "\x11" "into people's houses like this?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x157E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x30" "You again? " "\x11" "Didn't I tell you to leave us" "\x11" "alone?!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x157F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x3B" "\x17" "Don't!" "\x18" "\x11" "It's me! It's Pamela!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1580, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x30" "\x17" "Get out!" "\x18" "\x11" "Forget everything you've seen here" "\x11" "and get out!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1581, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...Father?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1582, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Pamela!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1583, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x31" "Father!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1584, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What have I been doing this whole" "\x11" "time?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1585, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x32" "You...haven't been doing" "\x11" "anything..." "\x11" "\x13" "\x12" "You had a bad dream." "\x11" "You were just having a little" "\x11" "nightmare." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1586, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x62" "...Pamela." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1587, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Um" "\x1F" "\x00" "\x04" "...What you did for my father..." "\x11" "\x1F" "\x00" "\x04" "Thank you." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1588, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But..." "\x11" "You helping us...It's a secret from" "\x11" "my father." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1589, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Whenever anything strange" "\x11" "happens, my father immediately" "\x11" "starts talking about doing" "\x11" "research..." "\x10" "and he does all kinds of crazy" "\x11" "things, so..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x158A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Once he calms down a bit, I think" "\x11" "I'll try convincing him to quit" "\x11" "researching in this dangerous" "\x11" "place and to go back to town." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x158B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "So..." "\x11" "If my father sees you again..." "\x11" "\x17" "...I'm sorry." "\x18" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x158C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Your strange power..." "\x11" "If father sees that, he'll surely" "\x11" "want to research it." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x158D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That's why..." "\x11" "I don't really want..." "\x11" "you to meet my father..." "\x11" "\x12" "I'm sorry to say such a thing..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x158E, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Who are you?" "\x11" "Don't just walk into people's" "\x11" "houses!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x158F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x63" "\x17" "Oh!" "\x11" "Isn't this a fairy?" "\x18" "\x11" "\x13" "\x12" "Is this yours, " "\x17" "young man?" "\x18" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1590, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I am the famed academic who" "\x11" "researches fairies, ghosts and" "\x11" "similar so-called supernatural" "\x11" "phenomena." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1591, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "By the way, the song, " "\x17" "Farewell to" "\x11" "Gibdos" "\x18" ", which the music box is" "\x11" "now playing, drives away Gibdos." "\x11" "\x12" "I discovered it after many years" "\x11" "of researching Gibdos." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1592, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "In regards to ghosts, there isn't" "\x11" "another academic who can match" "\x11" "my knowledge, so ask me anything" "\x11" "you like." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1593, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x64" "...It's been some time since I've a" "\x11" "seen a fairy this lively." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1594, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Say, " "\x17" "young man!" "\x18" "\x11" "Would you permit me to do" "\x11" "research on this fairy?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1595, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x63" "Oh! Hmmmm!" "\x11" "My Ghost Radar is reacting" "\x11" "fiercely." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1596, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But..." "\x11" "This is minutely different from its" "\x11" "usual response." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1597, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x64" "This is a verrrry " "\x1F" "\x00" "\x0A" "intriguing" "\x11" "response!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1598, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hmmm...You seem to be both" "\x11" "similar to a ghost and different" "\x11" "from one at the same time..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1599, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x64" "This is verrry " "\x1F" "\x00" "\x0A" "intriguing." "\x11" "\x13" "\x13" "\x12" "Could you remain here a while and" "\x11" "permit me to research you?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x159A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Are you curious about that" "\x11" "picture?" "\x11" "\x13" "\x12" "That is a mummified man. Its" "\x11" "scientific name is Gibdo." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x159B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "A tale in Ikana tells of a treasure" "\x11" "that rests at the bottom of the" "\x11" "\x01" "well " "\x00" "on the hilltop." "\x11" "\x12" "It seems the spirits of those who" "\x11" "became Gibdos upon entering the" "\x11" "well in search of that treasure" "\x11" "still linger inside" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x159C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It's been said going down there is" "\x11" "a petrifying experience. So even" "\x11" "the mummy hunter may become" "\x11" "mummified!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x159D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I even tried to go into that well" "\x11" "once myself..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x159E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x64" "Strangely enough, though, I don't" "\x11" "remember anything that happened" "\x11" "there." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x159F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, you never know what might" "\x11" "happen, so it's simply best not to" "\x11" "approach it." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15A0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Are you curious about that" "\x11" "picture?" "\x11" "\x13" "\x12" "That is the ghost of a ninja. Its" "\x11" "scientific name is " "\x03" "Garo Robe" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15A1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "They are merely shells that are" "\x11" "empty on the inside. They're the" "\x11" "shells of spies from an enemy" "\x11" "nation sent to investigate Ikana." "\x10" "They have been unable to forget" "\x11" "their living days. Even now their" "\x11" "spirits--emptiness cloaked in" "\x11" "darkness--continue to spy." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15A2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "According to rumor, those Garos" "\x11" "frequently appear near the ranch" "\x11" "on the far side of town." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15A3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Although they are said to be" "\x11" "shells, Garos are still ninja and" "\x11" "they will not show themselves in" "\x11" "front of people." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15A4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x64" "Yet there are many sightings near" "\x11" "the ranch..." "\x11" "That's strange." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15A5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x63" "\x17" "Oh! That mask is certainly a" "\x11" "Gibdo!" "\x18" "\x11" "\x13" "\x12" "\x17" "Young man!" "\x18" "\x11" "Where did you get that?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15A6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x64" "Hmmmm...The more I look at it, the" "\x11" "more this mask looks like a real" "\x11" "Gibdo to me." "\x11" "\x12" "With this mask, you probably could" "\x11" "convey your feelings to Gibdos." "\x11" "\x13" "\x12" "Perhaps you could even investigate" "\x11" "the " "\x01" "Gibdo life-form" "\x00" " itself!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15A7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Say, young man!" "\x18" "\x11" "Would you permit me to do" "\x11" "research on that mask?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15A8, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x30" "Aieeyeaaah! Get out!" "\x11" "...It's already too much!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15E0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x38" "\x80" "Thanks for stopping!" "\x11" "You're not from here, are you?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15E1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\xA7" "I sell " "\x02" "Magic Beans " "\x00" "to Deku" "\x11" "Scrubs, but I'd really like to leave" "\x11" "my hometown." "\x11" "\x12" "I'm hoping to find some success in" "\x11" "a livelier place!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15E2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But to open a business in another" "\x11" "place..." "\x11" "You need to go through the " "\x11" "proper channels first." "\x10" "\x1E" "\x3A" "\xD2" "Do you know what I mean?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15E3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\xA7" "Sorry...but I must get back to" "\x11" "business." "\x11" "\x13" "\x12" "You didn't understand my problem." "\x11" "Oh, well. Don't pay it any heed." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15E4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x38" "\x80" "Oh! That's a " "\x01" "Town Land Title" "\x11" "Deed" "\x00" "! I wish you'd let me have" "\x11" "that." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15E5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xD2" "I'll give you this land in return!" "\x11" "Deal?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15E6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm going off to town right now!" "\x11" "\x1E" "\x38" "\x80" "I'll leave the rest up to you!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15E7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x38" "\x80" "Thanks for stopping by!" "\x11" "I'm doing business with a focus on" "\x11" "a Deku Scrub clientele." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15E8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x39" "\x8C" "Actually, I want to do business at" "\x11" "the palace, but there's this big" "\x11" "octopus...and..." "\x11" "\x12" "Nothing really can be done about" "\x11" "it, so I set up shop here." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15E9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x3A" "\xD2" "Do you know what " "\x02" "magic beans" "\x11" "\x00" "are, sir?" "\x11" "I'll sell you one for " "\x06" "10 Rupees" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15EA, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Do you need any?" "\x11" " " "\x11" "\x02" "\xC2" "Yes" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x15EB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x38" "\x81" "Ah, well, that's too bad." "\x11" "If you ever want any, look me up." "\xE0" "\xBF" "", NULL);
