    EZTR_Basic_ReplaceText(0x1886, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It's time for the two of us to be" "\x11" "alone. Sorry, but get out!" "\xE0" "\xBF" "", NULL);
