    EZTR_Basic_ReplaceText(0x188C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, I have to get things ready" "\x11" "for tonight's business..." "\x11" "Please take care." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x188D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm openin' the shop..." "\x11" "Sorry, but ya gotta go." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x188E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x1E" "\x68" "\x45" "He's opening the shop!" "\x11" "We're in the way, so let's go." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x188F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "OK, it's closing time." "\x11" "See ya!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1890, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x60" "OK, it's closing time." "\x11" "Quick! Get outta here!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1891, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Soon, I will unite my spirit to cut" "\x11" "the moon, so you must leave here." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1892, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, I'm sorry. It's already time to" "\x11" "close up shop. Come again." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1893, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That's all for today, so hurry up" "\x11" "and go home!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1901, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Snapper" "\x05" "! The way these" "\x11" "things move, they never expose" "\x11" "the weak part of their body!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1902, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That's a " "\x00" "Mini Baba" "\x05" ". It won't attack" "\x11" "unless you get too close to it, so" "\x11" "watch your step!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1903, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "You've run inside a " "\x00" "Mad Jelly" "\x05" "." "\x11" "Since its body is so soft, normal" "\x11" "attacks won't do any good! Figure" "\x11" "out another way!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1904, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What?! You don't even know" "\x11" "about the " "\x00" "Skulltula" "\x05" "? It's protected" "\x11" "by a hard shell, but its stomach" "\x11" "is soft!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1905, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That's a " "\x00" "Red Chuchu" "\x05" ". It's nothing" "\x11" "really to be afraid of! It's not" "\x11" "unusual to find something in its" "\x11" "stomach that might be of use." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1906, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Blue Chuchu" "\x05" "..." "\x11" "This doesn't have anything inside" "\x11" "of it, so it's really just a blob of" "\x11" "water." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1907, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Don't tell me you don't know about" "\x11" "the " "\x00" "Deku Baba" "\x05" "! Cut it down when" "\x11" "it has extended its body and Deku" "\x11" "Nuts or Sticks will come out." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1908, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Bio Deku Baba" "\x05" "..." "\x11" "Just calm down and aim carefully!" "\x11" "And don't blame me if one hit" "\x11" "doesn't get rid of it!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1909, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Isn't that a " "\x00" "Deku Baba" "\x05" "?" "\x11" "But it looks a little withered..." "\x11" "Just cut it. You should at least" "\x11" "get a Deku Stick out of it." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x190A, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Dexihand" "\x05" "." "\x11" "Just be careful..." "\x11" "Look, it's not my fault if you get" "\x11" "too close and it grabs you!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x190B, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That's a " "\x00" "Nejiron" "\x05" "." "\x11" "Don't get too close to it." "\x11" "Sniff...Sniff..." "\x11" "It smells like gun powder!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x190C, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That's a " "\x00" "Giant Bee" "\x05" "." "\x11" "Don't ask me!" "\x11" "You can either fight or run..." "\x11" "It's up to you." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x190D, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What?! Don't you know about" "\x11" "the " "\x00" "Dodongo" "\x05" "? It moves slowly, so" "\x11" "you can circle around to its" "\x11" "backside. Got that?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x190E, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Deep Python" "\x05" ". Get close to" "\x11" "it and stun it. If you fail, it'll" "\x11" "getcha!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x190F, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Death Armos" "\x05" ", a temple guard..." "\x11" "Look at that red mark on its" "\x11" "chest! I know you've seen" "\x11" "something like that before..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1910, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What?! Don't you know about" "\x11" "the " "\x00" "Dinofols" "\x05" "? Use targeting" "\x11" "methods while defending. And " "\x11" "watch out for its fiery breath!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1911, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Don't tell me you don't know about" "\x11" "the " "\x00" "Fire Keese" "\x05" "! Defeat it before" "\x11" "it swoops down on you." "\x11" "I do not want to roast!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1912, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What?! Don't you know about" "\x11" "the " "\x00" "Keese" "\x05" "? Use Z Targeting when" "\x11" "it gets close. Even if it flies off," "\x11" "I'll follow it for you." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1913, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "You know about the" "\x00" " Armos" "\x05" ", right?" "\x11" "Shhhh! Don't touch it! Blow it up" "\x11" "before it wakes, please!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1914, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That's an " "\x00" "Eeno" "\x05" "." "\x11" "It's persistent!" "\x11" "...And it's susceptible to heat!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1915, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Isn't that a " "\x00" "Dragonfly" "\x05" "?" "\x11" "As long as you stay away from" "\x11" "its tail, it's no big danger." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1916, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Stick with using the basic" "\x11" "target methods while defending." "\x11" "...He's a different rank than those" "\x11" "other two lackeys, though..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1917, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It said that it's a " "\x00" "Garo" "\x05" "..." "\x11" "Just concentrate on blocking and" "\x11" "dodging those sharp swords!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1918, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That's the " "\x00" "Garo Master" "\x05" "..." "\x11" "You can't fight him like an" "\x11" "ordinary Garo. Just dodge those" "\x11" "swords..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1919, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Wart" "\x05" "." "\x11" "Once you've gotten rid of the" "\x11" "spheres that shield the main body," "\x11" "you can attack the eye." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x191A, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's " "\x00" "Gomess" "\x05" ". There'll be no end to" "\x11" "it if you can't get those bats" "\x11" "away from it. Does that shed any" "\x11" "light on the situation?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x191B, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hurry! Chase after it. Even if it" "\x11" "means throwing your own body" "\x11" "into it, do it so it'll stop!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x191C, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That's a " "\x00" "Blue Bubble" "\x05" "!" "\x11" "Quick! Run! Don't let it curse" "\x11" "you! If it comes after you, defend" "\x11" "yourself to block it!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x191D, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Use Z Targeting methods while" "\x11" "defending...The \"Unthinkable?\"" "\x11" "What could that possibly be" "\x11" "in a place as dark as this?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x191E, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Just keep defending and watch his" "\x11" "movements. I think I'm starting to" "\x11" "see his weak point!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x191F, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What?! Don't you know about the " "\x11" "\x00" "Skullwalltula" "\x05" "?" "\x11" "...Just don't touch it, all right?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1921, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hurry! Chase him until you get" "\x11" "your chance at him! But if you" "\x11" "get too close, you might regret" "\x11" "it!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1922, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Yellow Chuchu" "\x05" "." "\x11" "That's nothing to sweat about." "\x11" "It usually has something in its" "\x11" "stomach that's of use..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1923, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Takkuri" "\x05" "." "\x11" "Run! This bird steals your items!" "\x11" "C'mon! What are you doing just" "\x11" "standing around?!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1924, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What?! You don't know about the" "\x11" "\x00" "Red Bubble" "\x05" "? If it comes at you," "\x11" "get in the defensive position to" "\x11" "bounce it back...Got it?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1925, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hiploops" "\x05" " are hotheaded," "\x11" "so they'll charge if you look it in" "\x11" "the eye. If it comes at you, " "\x11" "assume the defensive position." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1926, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Hiploop" "\x05" ". Quickly dodge it" "\x11" "if it charges at you. But can't you" "\x11" "first do something about that" "\x11" "mask it's wearing?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1927, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Don't tell me you don't know about" "\x11" "the " "\x00" "Shell Blade" "\x05" "! It's impossible to" "\x11" "beat it if you aim for anything" "\x11" "but its ligament inside the shell." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1928, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "If you go near it now, you'll be" "\x11" "eaten! Aim at it from afar to" "\x11" "weaken it." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1929, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What are you doing?!?" "\x11" "There's no time to lose! Dive" "\x11" "underwater and attack it!" "\x11" "Hurry!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x192A, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "ReDead" "\x05" "..." "\x11" "If it catches you in its paralyzing" "\x11" "glare, you won't be able to move." "\x11" "Shake it off if you get caught!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x192C, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Black Boe" "\x05" "..." "\x11" "Just calm down and attack it!" "\x11" "Look, there are just a lot of them," "\x11" "that's all." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x192D, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Gibdo" "\x05" "." "\x11" "You won't be able to move if it" "\x11" "glares at you, so be careful!" "\x11" "Got it?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x192E, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Just its head and tail aren't" "\x11" "protected by its hard exoskeleton," "\x11" "so aim carefully. If only you were" "\x11" "the same size as it..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1930, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Wallmaster" "\x05" "! Keep an eye" "\x11" "out for it by watching for its" "\x11" "shadow on the floor. Get it before" "\x11" "it goes back up to the ceiling." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1931, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "You know the " "\x00" "Floormaster" "\x05" ", right?" "\x11" "If you don't do something about" "\x11" "its pieces before they can " "\x11" "reunite..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1932, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Remember your battles!" "\x11" "\x05" "When something resistant would" "\x11" "deflect your weapons, what was" "\x11" "its backside usually like?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1933, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Remember your battles!" "\x11" "\x05" "When you fought things that ran" "\x11" "around, didn't you battle them" "\x11" "using your own body?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1934, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Think about battles and weapons!" "\x11" "\x05" "When you had the chance before" "\x11" "an enemy was about to attack," "\x11" "didn't you usually try shooting it?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1935, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "You know about the " "\x00" "Iron" "\x11" "Knuckle" "\x05" ", right? Stay away from" "\x11" "its ax attack, then look for a" "\x11" "chance to retaliate." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1937, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "You know about the " "\x00" "Like Like" "\x05" "," "\x11" "right? It eats whatever you're" "\x11" "carrying. You'd better defeat it if" "\x11" "you want your stuff back." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1939, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What?! You don't know about the" "\x11" "\x00" "Beamos" "\x05" "? Don't let its beam" "\x11" "scare you. Just give it a good" "\x11" "blast!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x193A, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x193B, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Don't tell me you don't know about" "\x11" "the " "\x00" "Freezard" "\x05" "! Watch out for its" "\x11" "icy breath! I hate the c-c-cold!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x193C, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "White Boe" "\x05" "..." "\x11" "Just calm down and attack it!" "\x11" "Yeah, yeah, yeah...There are just" "\x11" "a lot of them, OK?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1942, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "You know about the " "\x00" "Octorok" "\x05" "," "\x11" "right? All you have to do is" "\x11" "deflect that rock it spits out." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1944, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "What?! You don't know about the" "\x11" "\x00" "Poe" "\x05" "? If you try to use Z" "\x11" "Targeting, it vanishes." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1945, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That's a " "\x00" "Gekko" "\x05" "." "\x11" "And it's pretty angry!" "\x11" "It's pretty weak, too. It really" "\x11" "shouldn't be making a fool of you." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1946, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Don't you know about the " "\x00" "Blue" "\x11" "Tektite" "\x05" "? Use Z Targeting to follow" "\x11" "it as it bounces!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1947, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "You know about the " "\x00" "Leever" "\x05" ", right?" "\x11" "It actually moves pretty fast." "\x11" "That's not exactly good news," "\x11" "is it?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1948, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Don't tell me you don't know about" "\x11" "the " "\x00" "Pea Hat" "\x05" "! Just remember that" "\x11" "its root area is soft!" "\xBF" "", NULL);
