    EZTR_Basic_ReplaceText(0x1954, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "The " "\x00" "pirate" "\x05" " found you!" "\x11" "Use Z targeting and look for your" "\x11" "chance. You're caught if you don't" "\x11" "win." "\xBF" "", NULL);
