    EZTR_Basic_ReplaceText(0x1958, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Guay" "\x05" ". You don't know about" "\x11" "this one? Just attack it before it" "\x11" "swoops down on you. That's" "\x11" "all there is to it." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1959, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Don't tell me you don't know about" "\x11" "the " "\x00" "Big Octo" "\x05" "! If you don't want" "\x11" "to be sucked in, keep your" "\x11" "distance. Aim from afar!" "\xBF" "", NULL);
