    EZTR_Basic_ReplaceText(0x195E, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "If you get close to him, you'll be" "\x11" "beaten! Do you understand me?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x195F, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "That's a " "\x00" "Gekko" "\x05" "." "\x11" "It gets itself all worked up and" "\x11" "then it just runs around." "\x11" "I hate it." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1960, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "It's a " "\x00" "Bad Bat" "\x05" ". If you don't do" "\x11" "something before it swoops down" "\x11" "on you...Well, just don't come" "\x11" "running to me!" "\xBF" "", NULL);
