    EZTR_Basic_ReplaceText(0x1F49, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x1E" "\x29" "\x25" "You!" "\x11" "\x13" "\x13" "\x12" "If I wasn't dealing with you," "\x11" "I wouldn't have gotten separated" "\x11" "from my brother!" "\x11" "\x12" "Well, don't just sit there, Deku" "\x11" "boy! Do something!!!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F4A, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x1E" "\x68" "\x50" "...Why are you looking at me like" "\x11" "that? What, is there something" "\x11" "stuck on my face?" "\x11" "\x12" "Will you stop staring and just" "\x11" "open that " "\x01" "door " "\x05" "for me?!?" "\x11" "\x13" "\x12" "Please!!! C'mon, a helpless, little" "\x11" "girl is asking you..." "\x11" "\x13" "So hurry up!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F4B, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x29" "\x35" "\x05" "Ohhhh, " "\x01" "Tael" "\x05" "..." "\x11" "I wonder if that child will be all" "\x11" "right on his own?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F4C, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Hey, wait for me!" "\x11" "Don't leave me behind!" "\x11" "\x13" "\x12" "So, um... " "\x11" "\x01" "That stuff back there" "\x05" "..." "\x11" "I...um...apologize, so..." "\x11" "So take me with you!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F4D, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "You wanna know about that" "\x11" "Skull Kid who just ran off, right?" "\x11" "\x13" "\x12" "Well, I just so happen to have an" "\x11" "idea of " "\x01" "where" "\x05" " he might be going." "\x11" "\x13" "\x12" "Take me with you and I'll help" "\x11" "you out. Deal?" "\x11" "\x13" "\x12" "Please?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F4E, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x1E" "\x68" "\x50" "\x17" "Good! So then it's" "\x11" "settled!" "\x18" "\x11" "\x13" "\x12" "Now then, I'll be your partner..." "\x11" "or at least until we catch that" "\x11" "Skull Kid..." "\x11" "\x12" "My name's " "\x01" "Tatl" "\x05" "." "\x11" "So, uh, it's nice to meet you" "\x11" "or whatever." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F4F, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Now that we've got all that" "\x11" "straightened out, can we stop" "\x11" "messing around and get moving?" "\x11" "\x12" "If I figure something out," "\x11" "press " "\xB6" " and I'll tell it to you." "\x11" "Hopefully, you'll manage to get by" "\x11" "without my help until then!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F50, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Aww, boo-hoo." "\x11" "Why the sad face?" "\x11" "\x13" "\x12" "\x1E" "\x3A" "\x79" "I just thought I'd have a little fun" "\x11" "with you..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F51, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, come now..." "\x11" "Do you really think you can beat" "\x11" "me as I am now?" "\x11" "Fool!" "\x1D" "\x00" "\x14" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F52, 0x07, 0x23, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "In the land of Hyrule, there" "\x11" "echoes a legend. A legend held" "\x11" "dearly by the Royal Family that" "\x11" "tells of a boy..." "\x1C" "\x00" "\x5A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F53, 0x07, 0x23, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "A boy who," "\x11" "after battling evil and saving" "\x11" "Hyrule, crept away from the land" "\x11" "that had made him a legend..." "\x1C" "\x00" "\x5A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F54, 0x07, 0x23, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Done with the battles he once" "\x11" "waged across time, he embarked" "\x11" "on a journey. A secret and" "\x11" "personal journey..." "\x1C" "\x00" "\x5A" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F55, 0x07, 0x23, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "A journey in search of a " "\x11" "beloved and invaluable friend..." "\x1C" "\x00" "\x50" "\xBF" "", NULL);
