    EZTR_Basic_ReplaceText(0x1F62, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Did you..." "\x11" "Did you save me?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F63, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I thought they didn't want to be" "\x11" "friends with me..." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F64, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "But..." "\x11" "They hadn't forgotten about me..." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F65, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Friends are a nice thing to have..." "\x11" "\x1E" "\x3A" "\x7E" "Heh, heh." "\xBF" "", NULL);
