    EZTR_Basic_ReplaceText(0x1F68, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I know, I know!" "\x11" "Let's do something!" "\xBF" "", NULL);
