    EZTR_Basic_ReplaceText(0x1F71, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "Well, both of us have gotten what" "\x11" "we were after..." "\x11" "\x1F" "\x00" "\x14" "So this is where you and I part" "\x11" "ways, isn't it?" "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1F72, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x1F" "\x00" "\x0A" "You know...it was kind of fun." "\xBF" "", NULL);
