    EZTR_Basic_ReplaceText(0x1FA4, 0x00, 0x31, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x7D" "You've met with a terrible fate," "\x11" "haven't you?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1FA5, 0x00, 0x11, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x7D" "I own the" "\x01" " Happy Mask Shop" "\x00" "." "\x11" "I travel far and wide in search of" "\x11" "masks..." "\x11" "\x12" "During my travels, a very" "\x11" "important " "\x01" "mask " "\x00" "was stolen from" "\x11" "me by an imp in the woods." "\x11" "\x12" "So here I am at a loss..." "\x11" "And now I've found you." "\x15" "\xBF" "", NULL);
