    EZTR_Basic_ReplaceText(0x1FB0, 0x00, 0x31, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x7E" "Were you able to recover your" "\x11" "\x01" "precious item" "\x00" " from that imp?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x1FB1, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh! Oh! Ohhh!!!" "\x11" "You got it! You got it!" "\x11" "You got it! You got it!!!" "\x15" "\xBF" "", NULL);
