    EZTR_Basic_ReplaceText(0x201D, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You are already leaving this land" "\x11" "of " "\x01" "Hyrule" "\x00" ", aren't you?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x201E, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Even though it was only a short" "\x11" "time, I feel like I've known you" "\x11" "forever." "\x11" "\x12" "I'll never forget the days we" "\x11" "spent together in Hyrule..." "\x11" "\x13" "\x12" "And I believe in my heart that a" "\x11" "day will come when I shall meet" "\x11" "you again..." "\x11" "\x12" "Until that day comes, please..." "\x11" "Take this..." "\xBF" "", NULL);
