    EZTR_Basic_ReplaceText(0x2030, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "He was trying to destroy" "\x11" "everything around him!" "\x11" "That is not the same as a " "\x01" "lonely" "\x11" "child" "\x05" "! We can't allow that!" "\xBF" "", NULL);
