    EZTR_Basic_ReplaceText(0x203E, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x68" "\x51" "\x06" "I don't always want to be running" "\x11" "away!" "\x11" "\x13" "\x12" "If only I had been stronger, the" "\x11" "Skull Kid wouldn't have..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x203F, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x68" "\x50" "\x05" "I understand. I'll go!" "\xBF" "", NULL);
