    EZTR_Basic_ReplaceText(0x208E, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x1F" "\x00" "\x14" "\"F" "\x1F" "\x00" "\x14" "o" "\x1F" "\x00" "\x14" "r" "\x1F" "\x00" "\x14" "g" "\x1F" "\x00" "\x14" "i" "\x1F" "\x00" "\x14" "v" "\x1F" "\x00" "\x14" "e " "\x1F" "\x00" "\x14" "y" "\x1F" "\x00" "\x14" "o" "\x1F" "\x00" "\x14" "u" "\x1F" "\x00" "\x14" "r " "\x1F" "\x00" "\x14" "f" "\x1F" "\x00" "\x14" "r" "\x1F" "\x00" "\x14" "i" "\x1F" "\x00" "\x14" "e" "\x1F" "\x00" "\x14" "n" "\x1F" "\x00" "\x14" "d.\"" "\x11" "\x00" "\x13" "\x05" "\x1F" "\x00" "\x14" "Forgive our friend?" "\x11" "\x00" "\x12" "\x05" "\x1E" "\x68" "\x45" "What do you mean by forgive?" "\x11" "Huh? What friend?" "\x1C" "\x00" "\x1E" "\xBF" "", NULL);
