    EZTR_Basic_ReplaceText(0x20B2, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The" "\x01" " frogs" "\x00" " that are supposed to" "\x11" "gather in the mountains when" "\x11" "\x01" "spring" "\x00" " arrives are elsewhere." "\x11" "\x12" "You need Don Gero's mask to" "\x11" "bring them together." "\x11" "\x13" "\x12" "The frogs in " "\x01" "Clock Town" "\x00" ", " "\x01" "the" "\x11" "swamp" "\x00" ", " "\x01" "Woodfall Temple" "\x00" " and" "\x11" "\x01" "Great Bay Temple" "\x00" " make four..." "\xBF" "", NULL);
