    EZTR_Basic_ReplaceText(0x20B4, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "To get Evan to listen to Mikau" "\x11" "and Japas's song from their music" "\x11" "session, you should not try" "\x11" "demonstrating it as Mikau." "\x10" "It seems if you pose as someone" "\x11" "\x01" "unrelated" "\x00" " to the band and begin" "\x11" "playing it, you just might get" "\x11" "him to lend an ear." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x20B5, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you use the " "\x01" "Lens of Truth" "\x00" " near" "\x11" "here and speak to the " "\x01" "man" "\x00" " you" "\x11" "find..." "\x11" "\x12" "you may earn a " "\x01" "mask" "\x00" " that can" "\x11" "enable you to blend into" "\x11" "backgrounds and move about" "\x11" "without being noticed." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x20B6, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It seems the " "\x01" "ReDeads " "\x00" "that appear" "\x11" "in Ikana Castle start dancing when" "\x11" "the " "\x01" "Captain's Hat" "\x00" ", " "\x01" "Gibdo Mask" "\x00" " or" "\x11" "\x01" "Garo's Mask " "\x00" "are worn." "\x10" "But that does not change things" "\x11" "much..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x20B7, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x01" "Pamela" "\x00" ", who lives in the music box" "\x11" "house, comes out every " "\x01" "two" "\x11" "minutes " "\x00" "when the " "\x01" "music box" "\x00" " is" "\x11" "playing." "\x10" "But it seems she will also come" "\x11" "out if she hears a " "\x01" "bomb" "\x11" "\x00" "explode..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x20B8, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It seems you can become a Milk" "\x11" "Bar member if you do a " "\x01" "good deed" "\x11" "\x00" "at the ranch." "\xBF" "", NULL);
