    EZTR_Basic_ReplaceText(0x2328, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "No using masks in the store" "\x11" "because of past indiscretions!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2329, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Kafei!" "\x11" "No, I don't know any such kid." "\x11" "I kid you not!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232A, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "If you wear something like that," "\x11" "you'll never be able to sleep." "\x11" "I kid you not!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232B, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, that's nice..." "\x11" "Maybe I can start carrying that in" "\x11" "my store..." "\x11" "I kid you not!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232C, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This isn't \"members-only,\" so take" "\x11" "that thing off." "\x11" "I kid you not!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232D, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x52" "That's great for a young kid." "\x11" "Delivery is hard work." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232E, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x52" "Oh! Who's the lucky lady?" "\x11" "Congratulations." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232F, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "My shop is small, so don't go" "\x11" "dancing up a storm in here!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2330, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That is one bizarre getup you've" "\x11" "got on your head. Take it off..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2331, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "That's weird!" "\x11" "I thought somebody had walked in" "\x11" "here." "\x11" "\x12" "Ah, well. I have to get ready for" "\x11" "the night shift, anyway." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2332, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "Don't go leading some parade" "\x11" "through a little place like this." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2333, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "Careful! Don't go blowing yourself" "\x11" "up in a place like this..." "\x11" "I kid you not!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2334, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Nah, I don't know that kid. And," "\x11" "the manager's not here now, so I" "\x11" "really can't help you." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2335, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6C" "I'm, like, embarrassed to wear" "\x11" "that, so I'm not gonna be a" "\x11" "member..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2336, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I entered to win some concert" "\x11" "tickets...Don't ya have anything" "\x11" "to deliver to me?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2337, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6D" "Ahh, I wanna find a girlfriend and" "\x11" "get married soon, too..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2338, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6D" "Whoa! Is that a skull?" "\x11" "That's cool!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2339, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "..." "\x11" "\x13" "\x13" "\x12" "We don't get many customers, so" "\x11" "why does the boss have so much" "\x11" "money?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x233A, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Isn't that, like, kind of dangerous?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x233B, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x2A" "Oh my! You've collected some" "\x11" "weird masks!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x233C, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, Kafei?" "\x11" "The mayor's son..." "\x11" "Now that you mention it, I haven't" "\x11" "seen him lately." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x233D, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh...You've collected some nice" "\x11" "masks!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x233E, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x2B" "Oooh! That's sooo cute!" "\x11" "I want to eat it!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x233F, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh! You've collected some cute" "\x11" "masks!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2340, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, are you a member of Latte," "\x11" "little guy? That's great!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2341, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, the Circus Leader's Mask!" "\x11" "He comes here a lot." "\x11" "\x13" "\x12" "He always says how his brothers" "\x11" "are at the ranch..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2342, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x2B" "Oh, nice job on those deliveries." "\x11" "So, do you wanna play?" "\x11" "\x13" "\x12" "But not when you're on the job," "\x11" "right?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2343, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x2A" "Oh, that's nice." "\x11" "Who's getting married?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2344, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, you're quite pretty..." "\x11" "But aren't I prettier?" "\x11" "Just kidding..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2345, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x2C" "Well, you've collected some" "\x11" "frightful masks!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2346, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x2C" "I can't stand...frogs." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2347, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What should I do for today's" "\x11" "treasure chest prize? " "\x11" "\x13" "\x12" "...I know, I'll give a good prize to" "\x11" "someone who pays a lot..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2348, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, where did you get that" "\x11" "mask? C'mon, tell me!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2349, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I used to see him by the Laundry" "\x11" "Pool sometimes. Hey, who is" "\x11" "he? What did he do?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x234A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm full of energy without even" "\x11" "wearing that mask!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x234B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I have that too!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x234C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You're a grown-up!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x234D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You can look in the postboxes..." "\x11" "I wish I could!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x234E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We're too young for that mask!" "\xE0" "\xBF" "", NULL);
