    EZTR_Basic_ReplaceText(0x2350, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I don't need a weird mask like" "\x11" "that!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2351, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Where did you get that mask?" "\xE0" "\xBF" "", NULL);
