    EZTR_Basic_ReplaceText(0x2741, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "........." "\x11" "\x13" "\x13" "\x12" "\x1E" "\x69" "\x5C" "This is a training center for" "\x11" "studying the way of the sword, so" "\x11" "I will teach anyone who has a" "\x11" "sword... " "\x10" "But first, leave that mask at" "\x11" "home..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2742, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Why do you wear a ninja's mask?" "\x11" "Do you wish to become a ninja in" "\x11" "the future?" "\x11" "\x12" "How nice. The innocence of" "\x11" "children..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2743, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "......" "\x11" "\x1E" "\x69" "\x5C" " Do you really wish to study the" "\x11" "sword?" "\x11" "\x12" "I can't find the will to teach you" "\x11" "when their milk has no freshness..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2744, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This is a training center for" "\x11" "studying the sacred sword!" "\x11" "Why that mask? How ugly and" "\x11" "sorrowful." "\x10" "If you wish to study the sword," "\x11" "first remove that strange" "\x11" "plaything." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2745, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ahh...You always do a wonderful job" "\x11" "delivering the mail." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2746, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, congratulations." "\x11" "Did a friend get married?" "\x11" "Mmm...To be young..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2747, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Hey, that's not bad. That girl's" "\x11" "mask is very beautiful!" "\x18" " I'll lose my" "\x11" "focus if I try to instruct you" "\x11" "while you're wearing that." "\x10" "Leave it at home." "\x11" "Or...I could keep it for you." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2748, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Frightening! That mask!" "\x11" "It's frightening!!!" "\x18" "\x11" "\x13" "\x12" "That scares me." "\x11" "Take it off! Take it off!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2749, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm no good at singing, so I won't" "\x11" "sing. Not even if you wear that!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x274A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "......" "\x11" "Why that mask?" "\x11" "Are you making fun of me? If" "\x11" "you're making fun of me, be gone!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x274B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Waaah!" "\x18" "\x11" "\x13" "\x13" "\x12" "If you wish to study the way of" "\x11" "the sword, remove that mask! It" "\x11" "looks like something I saw in a " "\x11" "bad dream..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x274C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hmm?" "\x11" "...Is someone there???" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x274D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x5B" "This is a training center for the" "\x11" "sacred sword!" "\x11" "\x13" "\x12" "Do not wear that mask and march" "\x11" "around in here! If you wish to do" "\x11" "that, go outside!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x274E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x5B" "This is a training center for" "\x11" "teaching the sacred sword!" "\x11" "Why do you wear that mask?" "\x11" "\x12" "I cannot allow such an evil weapon" "\x11" "in here. Come back when you are" "\x11" "ready!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x274F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x5B" "This is the training center of the" "\x11" "sacred sword! Why do you wear" "\x11" "that mask?" "\x11" "\x12" "I am not stinky!" "\x11" "\x17" "I take a bath at least once a" "\x11" "month!" "\x18" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2774, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6F" "I'm currently on the job." "\x11" "If I stop to talk, it will disrupt my" "\x11" "schedule." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2775, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6F" "According to my schedule, it is" "\x11" "now my nap time." "\x11" "\x13" "\x12" "If my schedule is disrupted by" "\x11" "even a few seconds, letter" "\x11" "delivery will be delayed..." "\x11" "Public service is very hard." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2776, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2777, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This is a problem...A real problem." "\x11" "Not a single letter was mailed..." "\x11" "\x13" "\x12" "What should I do this afternoon..." "\x11" "I wish someone would tell me." "\xBF" "", NULL);
