    EZTR_Basic_ReplaceText(0x2779, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...You're disrupting me!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x277A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Last night, I wrote a letter to" "\x11" "myself and deposited it in a post" "\x11" "box..." "\x11" "\x12" "I just retrieved it. This afternoon," "\x11" "I shall deliver that letter!" "\x11" "Hrr, hrr!" "\xBF" "", NULL);
