    EZTR_Basic_ReplaceText(0x277E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Th-this is a priority mail seal!" "\x11" "This is the highest of priorities." "\x11" "I shall deliver it!" "\xBF" "", NULL);
