    EZTR_Basic_ReplaceText(0x2784, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Deposit mail here." "\x11" "\x1F" "\x00" "\x0A" "\x1E" "\x28" "\x4C" "\x17" "Ka-ching!" "\x18" "\x19" "\xBF" "", NULL);
