    EZTR_Basic_ReplaceText(0x296B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...Listen, when someone asks you" "\x11" "that, you say yes." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x296C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Anju trusted you." "\x11" "I shall also trust you." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x296D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I am Kafei." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x296E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x05" "\x1E" "\x68" "\x45" "The Kafei we're looking for is an" "\x11" "\x01" "adult" "\x05" ". When I look at you, I just" "\x11" "see a " "\x01" "child" "\x05" "." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x296F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I was turned into this by a" "\x11" "strange imp wearing a mask..." "\x11" "\x13" "\x12" "But I'm not hiding because I look" "\x11" "this way." "\x15" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2970, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "When I was turned into this," "\x11" "I went to see the Great Fairy in" "\x11" "the shrine near the " "\x01" "North Gate" "\x00" "..." "\x11" "\x12" "But on the way, my precious mask" "\x11" "--" "\x01" "a wedding ceremony mask" "\x00" "--was" "\x11" "stolen from me by some " "\x01" "prancing" "\x11" "\x00" "man with a " "\x01" "grinning" "\x00" " face!" "\xBF" "", NULL);
