    EZTR_Basic_ReplaceText(0x2AE2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x50" "Oh. That's the greeting used" "\x11" "among us Zora." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2AE3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Where's your momma, sonny? Huh?" "\x11" "You came here by yourself? Well," "\x11" "aren't you a big boy?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2AE4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Once you get older, sonny, come" "\x11" "see The Indigo-Go's perform live at" "\x11" "Zora Hall." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2AE5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh dear, are you a student of" "\x11" "Deku Elementary?" "\x11" "Where's your teacher?" "\x11" "\x12" "You shouldn't be here. Field trips" "\x11" "go next door. Tell your teacher" "\x11" "that." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2AE6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Did you find your teacher?" "\x11" "Your teacher's not here???" "\x11" "Well, then I don't know what to do" "\x11" "with you..." "\xBF" "", NULL);
