    EZTR_Basic_ReplaceText(0x2AEB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, Gorman, I wish it was only" "\x11" "your face that was annoying me" "\x11" "right now." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2AEC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...So I may enter, miss?" "\x19" "\xBF" "", NULL);
