    EZTR_Basic_ReplaceText(0x2AF9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "The bar opens at night, sir." "\x11" "\x13" "\x13" "\x12" "And it's members-only. We refuse" "\x11" "people who don't have " "\x01" "proof of" "\x11" "membership" "\x00" "." "\x11" "\x12" "Well, now I'm getting things ready," "\x11" "so as long as you don't get in the" "\x11" "way of my cleaning, you can stay." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2AFA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We're called a " "\x01" "Milk Bar" "\x00" ", and we" "\x11" "serve the " "\x03" "milk of the night" "\x00" "." "\x11" "\x13" "\x12" "Our most popular, of course, is" "\x11" "\x01" "Chateau Romani" "\x00" ". It's a vintage" "\x11" "milk." "\x11" "\x12" "It comes from Romani Ranch, and" "\x11" "the current price is " "\x06" "200 Rupees" "\x00" "!" "\x11" "\x13" "\x12" "...You're not surprised?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2AFB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "There is one more surprising thing" "\x11" "about this milk..." "\x11" "\x13" "\x12" "It depends on who you ask, but" "\x11" "there are those who consider this" "\x11" "milk as a source of " "\x02" "Magic Power" "\x00" "!" "\x11" "It takes just one gulp they say!" "\x10" "It's expensive, but thankfully, it's" "\x11" "the one we serve the most." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2AFC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Last night, we got some fresh" "\x11" "milk in for the first time in quite" "\x11" "a while." "\x11" "\x12" "Finally, we can feel good about" "\x11" "our drinks' quality again." "\x11" "\x13" "\x12" "But that moon...Our regular" "\x11" "customers have all fled. So there" "\x11" "really isn't any good news." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2AFD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "To make things worse, we're short" "\x11" "on stock." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2AFE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "There is a road to the " "\x01" "south" "\x00" " of" "\x11" "town called " "\x01" "Milk Road" "\x00" "." "\x11" "\x13" "This could be someone's prank..." "\x10" "You see, the road is blocked by a" "\x11" "huge " "\x01" "boulder" "\x00" "." "\x11" "\x13" "I can't get any milk in from the" "\x10" "ranch now, so I can't please my" "\x11" "customers. It's terrible!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2AFF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...Are you looking for young Kafei," "\x11" "too?" "\x11" "\x13" "\x12" "It seems Madame Aroma still" "\x11" "doesn't know where he is..." "\x11" "But he's not the type to just run" "\x11" "off!" "\x10" "He must have a reason for not" "\x11" "showing himself." "\x11" "\x13" "\x12" "Just wait...When the time is right" "\x11" "and he's ready...he'll show himself." "\xBF" "", NULL);
