    EZTR_Basic_ReplaceText(0x2B03, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I came to drink!" "\x11" "I...I'm a customer!!!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B04, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well then, customer, the bar" "\x11" "opens at " "\x01" "10 o'clock at night" "\x00" "." "\x11" "Please wait 'til then. And besides" "\x11" "that..." "\x19" "\xBF" "", NULL);
