    EZTR_Basic_ReplaceText(0x2B0B, 0x06, 0x01, 0xFE, 0xFFFF, 0x0014, 0x00C8, false, "" "What'll it be?" "\x11" "\x13" "\x13" "\x12" "\x02" "\xC3" "Regular Milk: " "\x06" "20 Rupees" "\x11" "\x02" "Chateau: " "\x06" "200 Rupees" "\x11" "\x02" "Nothing" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B0C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You don't have enough " "\x06" "Rupees" "\x00" ", sir." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B0D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Give me a call when you make up" "\x11" "your mind." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B0E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Members of this club bring their" "\x11" "own glasses." "\x11" "\x13" "\x12" "We ask that you have an empty" "\x11" "bottle to drink out of when you" "\x11" "order." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B0F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "There is a road to the " "\x01" "south" "\x00" " of" "\x11" "town called " "\x01" "Milk Road" "\x00" "." "\x11" "\x13" "\x12" "Someone must've pulled a prank" "\x11" "out there, because the road is" "\x11" "blocked by a huge " "\x01" "boulder" "\x00" "." "\x11" "\x12" "I can't get any milk in from the" "\x11" "ranch, so I'm not sure if I should" "\x11" "recommend the Chateau Romani" "\x11" "to you." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B10, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...As you can see, all of our" "\x11" "customers have taken refuge." "\x11" "\x13" "\x12" "It may be my undoing, but I'm the" "\x11" "sort of fellow who'll stay at his" "\x11" "business through thick and thin." "\x11" "\x12" "And I continue standing here" "\x11" "at the counter hoping one of my" "\x11" "favorite customers will appear..." "\x11" "\x12" "And I wasn't wrong." "\x11" "See? You stopped in." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B11, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We've got some good milk in" "\x11" "tonight." "\x11" "\x13" "\x12" "Would you like some Romani for" "\x11" "your final moon viewing?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B12, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I remember when I was back at" "\x11" "the ranch. My brothers..." "\x11" "I wonder how they are..." "\xBF" "", NULL);
