    EZTR_Basic_ReplaceText(0x2B14, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...What? Hic!" "\x11" "\x13" "\x13" "\x12" "...Don't look at me! Hic!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B15, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Anyway, I'm just the despised" "\x11" "second son!" "\x11" "\x13" "\x12" "I can't handle horses like my older" "\x11" "brother!" "\x11" "\x13" "\x12" "I can't take care of horses like" "\x11" "my younger brother!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B16, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I left the ranch, came to know" "\x11" "the world of show business..." "\x11" "Traveled around..." "\x11" "But for what?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B17, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x68" "\x55" "...For nothing!!!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B18, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, I just had to enter the world" "\x11" "of entertainment, didn't I?" "\x11" "It's cold...Soooo cold..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B19, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh dear, are you all right with" "\x11" "not fleeing?" "\x11" "\x13" "\x12" "It looks like this is it for this" "\x11" "town, you know. You saw the" "\x11" "moon, didn't you? It's gotten so" "\x11" "huge." "\x10" "All the townsfolk have fled. You" "\x11" "should flee, too. Far away..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B1A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh dear, you're the one searching" "\x11" "for Kafei." "\x11" "\x13" "\x12" "How is it?" "\x11" "Have you found him?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B1B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "...Oh dear, is that so?" "\x11" "You haven't found him..." "\x11" "\x13" "\x12" "Well, that's enough." "\x11" "Good work..." "\x11" "Now you flee, too..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B1C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "And what does that have to do" "\x11" "with anything?" "\xE0" "\xBF" "", NULL);
