    EZTR_Basic_ReplaceText(0x2B1F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Wonderful! You really are an" "\x11" "expert!" "\x11" "\x13" "\x12" "Yes, yes, I'm sorry." "\x11" "My thanks." "\x11" "Yes, yes, it is your job, after all." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2B20, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm sorry." "\x11" "At this point in time, I can give" "\x11" "you only something like this." "\x11" "\x12" "Actually I wanted to give this to" "\x11" "you sooner..." "\x11" "Really!" "\xE0" "\xBF" "", NULL);
