    EZTR_Basic_ReplaceText(0x33C1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Mr. Barten was happy to get his" "\x11" "first delivery in quite a while!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33C2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Thank you..." "\x11" "You were pretty cool..." "\x11" "\x13" "\x12" "This isn't very big, but accept my" "\x11" "thanks!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33C3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "By doing one good deed, a child" "\x11" "becomes an adult." "\x11" "\x13" "\x12" "That " "\x01" "mask " "\x00" "is only given to a" "\x11" "limited number of adult customers." "\x11" "It's " "\x01" "proof of membership" "\x00" "." "\x11" "\x12" "I now acknowledge you as being" "\x11" "an adult!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33C4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I heard this from people who were" "\x11" "fleeing this way this morning...It's" "\x11" "terrible..." "\x11" "\x12" "They said that huge moon is going" "\x11" "to crash down onto the town" "\x11" "sometime tonight. I wonder if we'll" "\x11" "be all right here..." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33C5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Actually..." "\x11" "I know..." "\x11" "We're not safe here, either..." "\x11" "\x12" "I'm no expert on these things," "\x11" "but that's the feeling I get." "\x11" "\x1F" "\x00" "\x0A" "But..." "\x11" "\x12" "That's how life goes, I guess." "\x11" "There are some things in life that" "\x11" "you can't change no matter how" "\x11" "hard you try..." "\xBF" "", NULL);
