    EZTR_Basic_ReplaceText(0x33C7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x2E" "We're milking the cows tonight!" "\x11" "It's \"Chateau Romani.\" It's the" "\x11" "first time I get to drink it!" "\x11" "\x12" "Until now, my sister always said" "\x11" "\"Wait until you're an adult.\"" "\x11" "But why now?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33C8, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "........." "\x11" "\x13" "\x13" "\x12" "You've become an adult now," "\x11" "Romani...I see it in you." "\x11" "I'm acknowledging it." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33C9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x2F" "Then, does Romani get a mask," "\x11" "too?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33CA, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well, yes," "\x1F" "\x00" "\x0A" " I'll make one for you..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33CB, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Sleep with me in my bed tonight," "\x11" "OK, Romani?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33CC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Yes, sister." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33CD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Good night..." "\x11" "See you..." "\x1F" "\x00" "\x0A" "tomorrow...OK?" "\xBF" "", NULL);
