    EZTR_Basic_ReplaceText(0x33CF, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Would you like a ride?" "\x11" " " "\x11" "\x02" "\xC2" "Yes" "\x11" "No" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33D0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm sorry about giving you" "\x11" "only this. You have " "\x01" "Romani's" "\x11" "Mask" "\x00" ", don't you?" "\x11" "\x12" "It's proof of Milk Bar membership." "\x11" "Romani is a little expensive, but" "\x11" "please try it at the bar." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33D1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I guess it's been a while now" "\x11" "since our father died. I'm trying to" "\x11" "take care of the ranch, but things" "\x11" "have been getting unstable lately..." "\x1B" "\x00" "\x1E" "\x54" "\x68" "e cows always seem bothered" "\x11" "and frazzled, and I'm finding" "\x11" "broken bottles everywhere..." "\x11" "Who's doing it, I don't know..." "\x1C" "\x00" "\x1E" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33D2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "My sister Romani has been" "\x11" "worried, too. She's practicing using" "\x11" "a bow...She says it's to stop the" "\x11" "\"ghosts.\"" "\x1C" "\x00" "\x1E" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33D3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Say, what are the townsfolk" "\x11" "saying about that moon?" "\x11" "It's bigger than before, isn't it?" "\x1C" "\x00" "\x1E" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33D4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "In town...I have a friend." "\x11" "Her name's " "\x01" "Anju" "\x00" "..." "\x11" "\x1B" "\x00" "\x1E" "\x13" "\x41" "nju..." "\x11" "The day after tomorrow is her" "\x11" "wedding." "\x1C" "\x00" "\x1E" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33D5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I wonder if it will fall...that thing?" "\x1C" "\x00" "\x1E" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33D6, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "You did it!" "\x18" " " "\x1F" "\x00" "\x04" "You helped Cremia!" "\x11" "\x13" "\x13" "\x12" "You feel all warm and fuzzy!" "\x11" "inside! " "\x1F" "\x00" "\x0A" "Sigh..." "\x11" "You could get used to this!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33D7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Mr. Barten was happy to get his" "\x11" "first delivery in quite a while!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33D8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Thank you..." "\x11" "You were pretty cool..." "\x11" "\x13" "\x12" "This isn't very big, but accept my" "\x11" "thanks!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33D9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm sorry about giving you only" "\x11" "this. You already have " "\x01" "Romani's" "\x11" "Mask" "\x00" ", don't you?" "\x11" "\x12" "It's proof of Milk Bar membership." "\x11" "Chateau Romani is a little" "\x11" "expensive, but please try it at the" "\x11" "bar." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33F4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6D" "These guys are all roosters." "\x11" "Heh, heh!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33F5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6C" "I heard it from my gramps." "\x11" "Says the moon's gonna fall..." "\x11" "\x13" "\x12" "With somethin' that big, it's sure" "\x11" "to take this ranch down with it..." "\x11" "Hahhh..." "\x1F" "\x00" "\x14" "Oh, well." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33F6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "My only regret is that I won't" "\x11" "get to see these guys in their" "\x11" "prime as roosters." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x33F7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I don't really get it, but just" "\x11" "seein' these guys with a crest and" "\x11" "all..." "\x11" "\x12" "I don't have regrets about" "\x11" "anythin' anymore. I'm perfectly" "\x11" "satisfied. Here...You can have this" "\x11" "from me..." "\xE0" "\xBF" "", NULL);
