    EZTR_Basic_ReplaceText(0x3458, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What do you want?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3459, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x68" "\x55" "You know what this place is?" "\x11" "This is the Gorman Brothers' horse" "\x11" "training center!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x345A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You got no business here if you" "\x11" "got no horse." "\x11" "Now beat it! Scram!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x345B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x68" "\x55" "I told you this is a horse training" "\x11" "center! It means nuthin' if you" "\x11" "got no horse! Got it?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x345C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x52" "Hey, sir." "\x11" "Heh, heh...What brings you here?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x345D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We're the Gorman Brothers and" "\x11" "this is our horse training center..." "\x11" "Without a horse...you..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x345E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Now, now...Don't get angry." "\x11" "All right, if you don't have a" "\x11" "horse, go ahead and take a look" "\x11" "around." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x345F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This is just between you and me," "\x11" "but if you need a horse, there are" "\x11" "a bunch next door at Romani" "\x11" "Ranch." "\x10" "Some young girl's running it. I bet" "\x11" "she wouldn't notice if ya stole " "\x11" "yourself one!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3460, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x68" "\x55" "Hey, you!" "\x11" "What are you doin' in a place like" "\x11" "this?!?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3461, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We're the Gorman Bothers and" "\x11" "this our horse training center!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3462, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Don't come to a place like this" "\x11" "when you can't even ride a horse!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3463, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Won'tcha buy some fresh milk?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3464, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This is just between you and" "\x11" "me..." "\x11" "\x13" "\x12" "That milk they produce down" "\x11" "yonder at Romani Ranch is" "\x11" "watered down a bit. It's not worth" "\x11" "drinkin'." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3465, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x52" "We don't do that kinda thing here." "\x11" "Ours is the real deal. It's always" "\x11" "fresh and full of vitamins." "\x11" "\x12" "It's true! I'll sell it cheap just for" "\x11" "you. How about it?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3466, 0x06, 0x01, 0xFE, 0xFFFF, 0x0032, 0xFFFF, false, "" "\x06" "50 Rupees" "\x00" " will do ya for one" "\x11" "drink!" "\x11" "\x02" "\xC2" "I'll buy it" "\x11" "No thanks" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3467, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, really?" "\x11" "Milk this good'll cost you double in" "\x11" "town. This is true!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3468, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You don't have enough " "\x06" "Rupees" "\x00" "..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3469, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm only sellin' the milk! Where" "\x11" "d'ya expect me to put it? You" "\x11" "need an empty bottle if you want" "\x11" "some!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x346A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x68" "\x52" "Much obliged." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x346B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Buyin' milk?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x346C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We're different from Romani" "\x11" "Ranch. Our milk is fresh and full" "\x11" "of vitamins. This is true!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x346D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Is that pathetic thing your horse?" "\x11" "\x13" "\x13" "\x12" "I would've guessed that little thing" "\x11" "was a mule fer sure, ain't that" "\x11" "right, little brother?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x346E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Do ya think a horse that pathetic" "\x11" "would gallop if you pushed " "\xBB" "\x11" "forward? Or would it run " "\x01" "faster" "\x11" "\x00" "if you pressed " "\xB0" "?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x346F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This guy's funny!" "\x11" "Why don't you give us " "\x06" "10 Rupees" "\x11" "\x00" "for the chance to race against" "\x11" "us?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3470, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you win, we'll give you somethin'" "\x11" "nice, kid." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3471, 0x06, 0x01, 0xFE, 0xFFFF, 0x000A, 0xFFFF, false, "" "What'll you do?" "\x11" " " "\x11" "\x02" "\xC2" "Race" "\x11" "Don't race" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3472, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x80" "Then don't come to a place like" "\x11" "this on your horse!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3473, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "You gotta keep at least " "\x06" "10 Rupees" "\x11" "\x00" "handy! Why would you carry" "\x11" "around a nice wallet like that" "\x11" "then?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3474, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "It's a simple race. Just go " "\x01" "once" "\x11" "\x00" "around the track. If you can beat" "\x11" "us to the finish line, you " "\x01" "win" "\x00" "." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3475, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hyuh, hyuh." "\x11" "You ready?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3476, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x68" "\x7C" "Hyuh, hyuh!" "\x11" "We win!!!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3477, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you like, we'll let you race us" "\x11" "again." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3478, 0x06, 0x01, 0xFE, 0xFFFF, 0x000A, 0xFFFF, false, "" "What'll you do?" "\x11" "\x02" " " "\x11" "\xC2" "Race" "\x11" "Don't race" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3479, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "This guy's no fun!" "\x11" "That's why you don't succeed!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x347A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x68" "\x55" "I can't believe we lost!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x347B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Big bro, I wonder if we can give" "\x11" "that to this guy?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x347C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We gotta give him something. Well," "\x11" "he's a kid, so what could he do" "\x11" "with it? It should be fine..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x347D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "In exchange, you can't tell anyone" "\x11" "where you got this!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x347E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We gotta give ya something, " "\x11" "so you got yourself some milk," "\x11" "kid!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x347F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Urgh...I thought so..." "\x11" "No empty bottles!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3480, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, that's really too bad. And I" "\x11" "was really gonna give it to you," "\x11" "too. It's true!" "\x11" "...Too bad! Too bad!!" "\xE0" "\xBF" "", NULL);
