    EZTR_Basic_ReplaceText(0x3487, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Well it's been only that type of" "\x11" "folk coming 'round here lately." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3488, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Sorry, but this is no place for" "\x11" "you to take shelter." "\x11" "\x13" "\x12" "You say the moon's gonna fall" "\x11" "soon? Ha! That's silly talk!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3489, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x68" "\x55" "This is a horse training center!" "\x11" "It don't mean a thing if you don't" "\x11" "have a horse! Got it?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x348A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ah, sir, do you have some" "\x11" "business at the Gorman Brothers'" "\x11" "Ranch on such a terrible day?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x348B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey you! What you doing in a" "\x11" "place like this on a day like" "\x11" "today?!?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x348C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We're the Gorman Brothers and" "\x11" "this is our horse training center." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x348D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you don't hurry up and get" "\x11" "outta here, you'll get eaten by" "\x11" "that there moon!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x348E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x52" "Seems some monstrous Garos" "\x11" "appeared at Romani Ranch" "\x11" "yesterday." "\x11" "\x12" "And I heard the wagon carrying" "\x11" "their milk was attacked." "\x11" "\x13" "\x12" "I tell you, that's a dangerous" "\x11" "place..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x348F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Seems like we're the only ones" "\x11" "who have any milk left." "\x11" "Hyuh, hyuh." "\x11" "\x12" "If you like, I'll sell you some." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3490, 0x06, 0x01, 0xFE, 0xFFFF, 0x0032, 0xFFFF, false, "" "\x06" "50 Rupees" "\x00" " will do ya for one" "\x11" "drink!" "\x11" "\x02" "\xC2" "I'll buy it" "\x11" "No thanks" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3491, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, really!" "\x11" "Milk this good'll cost you double in" "\x11" "town. This is true!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3492, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x52" "Heh, heh...Much obliged." "\x11" "\x13" "\x13" "\x12" "From here on out the milk" "\x11" "business will be ours!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3493, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We're the only place you'll be able" "\x11" "to get milk from!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3494, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Shall I sell you some?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3495, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Is that your horse?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3496, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I bet even that horse runs a little" "\x11" "if you press " "\xBB" " forward. And it" "\x11" "probably runs " "\x01" "faster " "\x00" "if you press" "\x11" "\xB0" " while riding it." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3497, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "For " "\x06" "10 Rupees, " "\x00" "you can have the" "\x11" "opportunity to race against us..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3498, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We're in a good mood today." "\x11" "If you win, we'll give you" "\x11" "something good, kid." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x3499, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x68" "\x7C" "Heh, heh...We win!!!" "\x11" "We're on fire!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x349A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you want, we'll race you again..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x349B, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "What'll you do?" "\x11" " " "\x11" "\x02" "\xC2" "Race" "\x11" "Don't Race" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x349C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Then we're busy. Now be off!" "\x19" "\xBF" "", NULL);
