    EZTR_Basic_ReplaceText(0x349E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Big bro, I wonder if we can give" "\x11" "that to this guy?" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x349F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We gotta give him something." "\x11" "Besides, we don't need it anymore," "\x11" "so what's the big deal?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x34A0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "In exchange, we don't want you" "\x11" "telling anyone where you got this" "\x11" "from!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x34A1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We gotta give him something. And" "\x11" "that something is...milk!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x34A2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ugh...I thought so...You don't have" "\x11" "any empty bottles on you!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x34A3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x52" "Oh, too bad. And I was really" "\x11" "gonna give you some milk if you" "\x11" "had an empty bottle to put it in..." "\x11" "It's true! Tooooo bad!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x34A4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "And they say the world is a hard" "\x11" "place. Look at you! I'd say you're" "\x11" "pretty lucky!" "\xE0" "\xBF" "", NULL);
