    EZTR_Basic_ReplaceText(0x34A6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "We're generous guys, so if you" "\x11" "win, we'll give you something really" "\x11" "good, kid. It's true!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x34A7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, sir, shouldn't you take refuge" "\x11" "somewhere?" "\x11" "\x13" "\x12" "I mean, there's that rumor and all." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x34A8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "If you hang around here, you'll get" "\x11" "eaten by a spooky Garo!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x34A9, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ah, that mask..." "\x19" "\xBF" "", NULL);
