    EZTR_Basic_ReplaceText(0x34AD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "No! No! Noooo!" "\x11" "And the things that we, the" "\x11" "Gorman Brothers, have done..." "\x11" "\x12" "Grrrr..." "\x11" "We're the notorious Gorman" "\x11" "Brothers! We can't get all sappy" "\x11" "over stuff like this!" "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x34AE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "I'm sorry, but take that mask off." "\x11" "\x13" "\x13" "\x12" "I can't get anything done when" "\x11" "you gaze at me with that mask" "\x11" "on." "\xBF" "", NULL);
